INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','what''s for dinner','',NULL,'/wʌts fɔːr ˈdɪnər/','"What''s for dinner?" I asked Mom.','“晚饭吃什么?”我问妈妈。','What''s for dinner tonight — soup or noodles?','今晚吃什么——汤还是面?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','go shopping','',NULL,'/ɡoʊ ˈʃɑːpɪŋ/','Do we have to go shopping first?','我们得先去购物吗?','We go shopping every Saturday morning.','我们每周六上午去购物。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','be careful with','',NULL,'/bi ˈkerfl wɪð/','You must be careful with the knife.','用刀你必须小心。','Be careful with the hot pot.','小心那个热锅。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','cook together','',NULL,'/kʊk təˈɡeðər/','We must cook together more often.','我们真该多一起做饭。','The whole family likes to cook together.','全家人都喜欢一起做饭。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp1','choice','{"stem":"\"''You ___ wash your hands before you help,'' Mom said.\"(必须、务必)","options":["would","must","can","may"],"answer_index":1,"stem_cn":"“帮忙前你必须先洗手,”妈妈说。","explanation_cn":"主观上“必须、务必”,用 must + 动词原形。✓ You must wash your hands. ✗ can:能够;✗ may:也许/可以;✗ would:意愿,不表“必须”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp1','choice','{"stem":"\"''This soup ___ taste amazing — it smells great!'' my brother said.\"(对现在的肯定推测:一定)","options":["must","can","need","would"],"answer_index":0,"stem_cn":"“这汤闻着真香,一定特别好喝!”弟弟说。","explanation_cn":"对现在的肯定推测“一定”,用 must + 原形。✓ This soup must taste amazing. ✗ can:能够/也许;✗ need:此处不搭;✗ would:不表推测。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp1','choice','{"stem":"\"''You ___ be careful with the knife,'' Mom warned.\"(务必、一定要)","options":["would","could","might","must"],"answer_index":3,"stem_cn":"“用刀一定要小心,”妈妈提醒道。","explanation_cn":"“务必、一定要”,用 must。✓ You must be careful with the knife. ✗ could:能够/也许;✗ might:也许;✗ would:意愿。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp2','choice','{"stem":"\"''Do we ___ go shopping first?'' I asked.\"(客观上是否必须)","options":["must","have to","having to","must to"],"answer_index":1,"stem_cn":"“我们得先去买东西吗?”我问。","explanation_cn":"客观上“必须”,用 have to + 原形。✓ Do we have to go shopping first? ✗ must:此处需与 Do 连用作疑问,应用 have to;✗ must to:must 后不加 to;✗ having to:形式不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp2','choice','{"stem":"\"On busy days, Mom ___ cook for the whole family.\"(客观上必须)","options":["are to","have to","has to","must to"],"answer_index":2,"stem_cn":"忙的时候,妈妈得给全家做饭。","explanation_cn":"客观上“必须”,主语是 Mom(单数),用 has to。✓ Mom has to cook for the whole family. ✗ must to:must 后不加 to;✗ have to:主语单数应用 has to;✗ are to:表安排。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp2','choice','{"stem":"\"Yesterday we ___ buy more rice for dinner.\"(过去客观上不得不)","options":["had to","has to","will have to","must"],"answer_index":0,"stem_cn":"昨天我们不得不多买些米做晚饭。","explanation_cn":"过去客观上“不得不”,用 had to。✓ Yesterday we had to buy more rice. ✗ must:不表过去;✗ has to:一般现在;✗ will have to:将来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp3','choice','{"stem":"\"''No, we ___. We have everything we need,'' Mom said.\"(不必)","options":["must","needn''t","should","mustn''t"],"answer_index":1,"stem_cn":"“不用,该有的都有了,”妈妈说。","explanation_cn":"“不必、无需”,用 needn''t + 原形。✓ No, we needn''t. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp3','choice','{"stem":"\"''We ___ hurry — dinner isn''t until six-thirty,'' Mom said.\"(不必)","options":["don''t have to","need","must not","have to"],"answer_index":0,"stem_cn":"“我们不用赶——晚饭六点半才吃,”妈妈说。","explanation_cn":"“不必、没必要”,用 don''t have to。✓ We don''t have to hurry. ✗ must not:是“禁止”;✗ have to:是“必须”;✗ need:此处不搭。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp3','choice','{"stem":"\"''Dinner ___ be ready until six-thirty,'' she added.\"(不必、无需)","options":["has to","must","mustn''t","needn''t"],"answer_index":3,"stem_cn":"“晚饭不必六点半前做好,”她补充道。","explanation_cn":"“不必、无需”,用 needn''t。✓ Dinner needn''t be ready until six-thirty. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ has to:是“必须”。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp4','choice','{"stem":"\"''We ___ start cooking soon,'' Mom said.\"(应该、建议)","options":["would","should","need","must have"],"answer_index":1,"stem_cn":"“我们该动手做饭了,”妈妈说。","explanation_cn":"“应该、建议”,用 should + 原形。✓ We should start cooking soon. ✗ must have:对过去的推测;✗ need:不搭;✗ would:不表“应该”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp4','choice','{"stem":"\"''___ I chop the vegetables?'' I asked.\"(征求意见:该……吗)","options":["Should","Must","Do","Would"],"answer_index":0,"stem_cn":"“我来切菜吗?”我问。","explanation_cn":"征求意见“我该……吗”,用 Should 提到句首。✓ Should I chop the vegetables? ✗ Must:语气过强;✗ Do:与原形 chop 不搭作此意;✗ Would:委婉意愿,不表“该不该”。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp4','choice','{"stem":"\"''You ___ try it when it''s done,'' Mom laughed.\"(应该、建议)","options":["must have","need","would have","should"],"answer_index":3,"stem_cn":"“做好了你尝尝,”妈妈笑道。","explanation_cn":"“应该、建议”,用 should。✓ You should try it when it''s done. ✗ must have:对过去的推测;✗ need:不搭;✗ would have:与过去相反的假设。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp5','choice','{"stem":"\"''We ___ cook together more often — it''s fun!''\"(说话人自己强烈的感受、建议)","options":["must","have to","are to","had to"],"answer_index":0,"stem_cn":"“我们真该多一起做饭——太有意思了!”","explanation_cn":"说话人自己强烈的感受、建议,用 must。✓ We must cook together more often. ✗ have to:多表外在客观要求,这里是主观愿望;✗ had to:过去;✗ are to:表安排。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp5','choice','{"stem":"\"The recipe says we ___ add salt, though I don''t think we need it.\"(菜谱这一外在要求)","options":["has to","must to","are having to","have to"],"answer_index":3,"stem_cn":"菜谱说要加盐,不过我觉得不用。","explanation_cn":"菜谱这一外在要求,用 have to。✓ The recipe says we have to add salt. ✗ must to:must 后不加 to;✗ has to:主语是 we,应用 have to;✗ are having to:形式不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp5','choice','{"stem":"\"''You ___ wash your hands — that''s the kitchen rule.''\"(外在客观的规定)","options":["have to","has to","are to","must to"],"answer_index":0,"stem_cn":"“你得洗手——这是厨房规矩。”","explanation_cn":"外在客观的规定,用 have to。✓ You have to wash your hands — that''s the kitchen rule. ✗ must to:must 后不加 to;✗ has to:主语是 you,应用 have to;✗ are to:表安排。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp6','choice','{"stem":"\"Please ___ the vegetables into small pieces.\"(切、剁用哪个词)","options":["sing","sleep","chop","drink"],"answer_index":2,"stem_cn":"请把蔬菜切成小块。","explanation_cn":"“切、剁”是 chop。✓ chop the vegetables. ✗ drink:喝;✗ sleep:睡觉;✗ sing:唱歌。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp6','choice','{"stem":"\"Be careful with the sharp ___.\"(刀用哪个词)","options":["knife","plate","spoon","cup"],"answer_index":0,"stem_cn":"小心那把锋利的刀。","explanation_cn":"“刀”是 knife。✓ be careful with the knife. ✗ spoon:勺子;✗ cup:杯子;✗ plate:盘子。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp6','choice','{"stem":"\"This ___ smells great and tastes amazing.\"(汤用哪个词)","options":["chair","book","soup","shoe"],"answer_index":2,"stem_cn":"这汤闻着香、喝着也好。","explanation_cn":"“汤”是 soup。✓ This soup smells great. ✗ chair:椅子;✗ book:书;✗ shoe:鞋。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"美语里\"炉灶\"说:","options":["stove","cooker","oven-box","heater"],"answer_index":0,"explanation_cn":"美语“炉灶”说 stove;英式说 cooker。✓ She put the pot on the stove. 她把锅放在炉灶上。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"美语里\"水龙头\"说:","options":["valve","spout","faucet","tap"],"answer_index":2,"explanation_cn":"美语“水龙头”说 faucet;英式说 tap。✓ Turn off the faucet. 关掉水龙头。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"chop 的意思是:","options":["烤","喝","洗","切,剁"],"answer_index":3,"explanation_cn":"chop = 切、剁。✓ chop the vegetables 切菜。\n顺带记:喝 = drink;洗 = wash;烤 = bake."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"knife 的意思是:","options":["杯子","盘子","刀","勺子"],"answer_index":2,"explanation_cn":"knife = 刀。✓ careful with the knife 用刀小心。\n顺带记:勺子 = spoon;杯子 = cup;盘子 = plate."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"taste 的意思是:","options":["听","看","闻","尝;有……的味道"],"answer_index":3,"explanation_cn":"taste = 尝;有……的味道。✓ This soup must taste amazing 这汤一定很好喝。\n顺带记:闻 = smell;看 = look;听 = listen."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"remind 的意思是:","options":["提醒","忘记","表扬","责备"],"answer_index":0,"explanation_cn":"remind = 提醒。✓ Mom reminded me 妈妈提醒我。\n顺带记:忘记 = forget;责备 = blame;表扬 = praise."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 1 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":1,"options":["should","must have","need","would"],"answer_index":0,"explanation_cn":"“应该、建议”,用 should。✓ We should start cooking soon.\n✗ must have:对过去的推测;✗ need:不搭;✗ would:不表“应该”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 2 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":2,"options":["have to","must","must to","having to"],"answer_index":0,"explanation_cn":"客观上“必须”,用 have to。✓ Do we have to go shopping first?\n✗ must:此处作疑问需 have to;✗ must to:must 后不加 to;✗ having to:形式不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 3 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":3,"options":["needn''t","mustn''t","must","should"],"answer_index":0,"explanation_cn":"“不必、无需”,用 needn''t。✓ No, we needn''t.\n✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 4 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":4,"options":["must","can","may","would"],"answer_index":0,"explanation_cn":"主观上“必须、务必”,用 must。✓ You must wash your hands.\n✗ can:能够;✗ may:也许/可以;✗ would:意愿。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',8,NULL,'choice','{"stem":"When will Dad be home for dinner?","options":["At five","At eight","At seven","At six"],"answer_index":3,"explanation_cn":"课文说 \"Dad will be home at six.\""}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',8,NULL,'choice','{"stem":"Did they have to go shopping first?","options":["Yes, they were out of food","Yes, they needed rice","No, they had everything they needed","No, the store was closed"],"answer_index":2,"explanation_cn":"课文说 \"No, we needn''t. We have everything we need.\""}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',8,NULL,'choice','{"stem":"What must the child do before helping?","options":["Call Dad","Wash their hands","Set the table","Turn on the oven"],"answer_index":1,"explanation_cn":"课文说 \"You must wash your hands before you help.\""}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',9,NULL,'choice','{"stem":"你想说\"我们得先去购物吗?\"(客观上是否必须,用 do...have to):","options":["Do we must go shopping first?","Do we have to go shopping first?","Must we to go shopping first?","Have we to going shopping first?"],"answer_index":1,"explanation_cn":"客观上是否必须,用 do...have to + 原形。✓ Do we have to go shopping first? 场合:问某件事是不是非做不可。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',9,NULL,'choice','{"stem":"你想说\"不,我们不必。需要的都有了\"(不必,用 needn''t):","options":["No, we needn''t. We have everything we need.","No, we don''t must. We have everything we need.","No, we mustn''t. We have everything we need.","No, we haven''t to. We have everything we need."],"answer_index":0,"explanation_cn":"“不必、无需”,用 needn''t。✓ No, we needn''t. We have everything we need. 场合:回答“不必这么做”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',9,NULL,'choice','{"stem":"你想说\"帮忙前你必须洗手\"(必须,用 must):","options":["You should washed your hands before you help.","You must to wash your hands before you help.","You must wash your hands before you help.","You have to washing your hands before you help."],"answer_index":2,"explanation_cn":"主观上“必须、务必”,用 must + 原形。✓ You must wash your hands before you help. 场合:提出一个必须遵守的要求。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"chop 的意思是:","options":["喝","烤","切,剁","洗"],"answer_index":2,"explanation_cn":"chop = 切、剁。✓ chop the vegetables 切菜。\n顺带记:喝 = drink;洗 = wash;烤 = bake."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"soup 的意思是:","options":["汤","椅子","鞋","书"],"answer_index":0,"explanation_cn":"soup = 汤。✓ This soup smells great 这汤闻着真香。\n顺带记:椅子 = chair;书 = book;鞋 = shoe."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"''Do we ___ go shopping first?'' I asked.\"(客观上是否必须)","options":["having to","must to","must","have to"],"answer_index":3,"stem_cn":"“我们得先去买东西吗?”我问。","explanation_cn":"客观上“必须”,用 have to。✓ Do we have to go shopping first?\n✗ must:此处作疑问需 have to;✗ must to:must 后不加 to;✗ having to:形式不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"''No, we ___. We have everything we need.''\"(不必)","options":["needn''t","should","must","mustn''t"],"answer_index":0,"stem_cn":"“不用,该有的都有了。”","explanation_cn":"“不必、无需”,用 needn''t。✓ No, we needn''t.\n✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"what''s for dinner\" 的意思是:","options":["为了晚饭","谁做晚饭","晚饭之前","晚饭吃什么"],"answer_index":3,"explanation_cn":"what''s for dinner = 晚饭吃什么。✓ \"What''s for dinner?\" I asked Mom。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"be careful with\" 的意思是:","options":["小心对待、当心","关心某人","忙于……","充满……"],"answer_index":0,"explanation_cn":"be careful with = 小心对待、当心。✓ You must be careful with the knife。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"What did Mom remind the child to do?","options":["Call Dad","Wash their hands","Buy more rice","Set the table"],"answer_index":1,"passage":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 \"You must wash your hands before you help.\""}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"When does dinner need to be ready?","options":["By six-thirty","By noon","Right away","By five o''clock"],"answer_index":0,"passage":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 dinner needn''t be ready until six-thirty——即六点半前好就行。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"When will Dad be home?","options":["At seven","At five","At six","At eight"],"answer_index":2,"audio":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 \"Dad will be home at six.\""}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"What must the child be careful with?","options":["The knife","The phone","The door","The window"],"answer_index":0,"audio":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 \"You must be careful with the knife.\""}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l91',2,12,91,'Three People in a Hot-Air Balloon','热气球上的三个人','复习 KS19/43/67 表示“能够/做成”的说法(收官包·干净课美语化):can / could(能力)、be able to(各时态的能力,尤其 was/were able to 表某次成功做到)、manage to(费劲设法做成)、can''t / couldn''t(不能),以及三者的辨析(某次成功做到用 was able to / managed to,不用 could)','去年夏天,三个朋友有幸坐上了一次热气球。“你们都挤得进吊篮吗?”飞行员问。“我们试试看!”他们说。不一会儿,他们就能俯瞰脚下整片山谷。可风很大,飞行员没法轻松掌舵。“别担心——我能应付,”他镇定地说。紧张了一分钟后,他设法让气球掉了头。他们谁都不曾从空中看过自己的镇子。“真不敢相信有这么美!”其中一个人说。最后,飞行员把气球安全地降落在一片田野里。他们经历了一生难忘的冒险——而且没有一个人受伤。','{"q":"Listen and answer — What did the three friends do last summer?","options":["Joined a hot-air balloon ride","Sailed across a lake","Climbed a tall mountain","Rode horses in a field"],"answer_index":0}'::jsonb,'{"title":"复习 KS19/43/67 “能够/做成”的说法","intro":"本课复习几种表示“能够、做到”的说法:①can / could——表能力(They could see the whole valley);②be able to——同样表能力,但可用于各种时态,尤其 was/were able to 表“某一次成功做到”(The pilot was able to land safely);③manage to——“费了一番劲、设法做成”(He managed to turn the balloon around);④can''t / couldn''t——“不能、无法”(The pilot couldn''t steer easily)。辨析要点:表“某一次具体成功做到了”,用 was able to 或 managed to,而不用 could;could 多用于“过去一贯具备的能力”。","table":{"headers":["说法","例子"],"rows":[["can / could(能力)","They could see the whole valley."],["be able to(某次做到)","The pilot was able to land safely."],["manage to(设法做成)","He managed to turn the balloon around."],["can''t / couldn''t(不能)","The pilot couldn''t steer easily."],["辨析","某次成功做到 → was able to / managed to,不用 could。"]]},"specialRules":[{"rule":"美语“度假”说 vacation(英式 holiday);“秋天”说 fall(英式 autumn)。本课已按美语写。","mark":"vacation / fall"},{"rule":"表“过去某一次费劲成功做到”,用 was able to 或 managed to,不用 could;could 用于“过去一贯的能力”。","mark":"could vs managed to"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l91',1,NULL,'Last summer, three friends were able to join a hot-air balloon ride. "Can you all fit in the basket?" the pilot asked. "We can try!" they said.','去年夏天,三个朋友有幸坐上了一次热气球。“你们都挤得进吊篮吗?”飞行员问。“我们试试看!”他们说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l91',2,NULL,'Soon they could see the whole valley below them. But the wind was strong, and the pilot couldn''t steer easily.','不一会儿,他们就能俯瞰脚下整片山谷。可风很大,飞行员没法轻松掌舵。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l91',3,NULL,'"Don''t worry — I can handle it," he said calmly. After a tense minute, he managed to turn the balloon around.','“别担心——我能应付,”他镇定地说。紧张了一分钟后,他设法让气球掉了头。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l91',4,NULL,'None of them had ever been able to see their town from the sky before. "I can''t believe how beautiful it is!" one of them said.','他们谁都不曾从空中看过自己的镇子。“真不敢相信有这么美!”其中一个人说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l91',5,NULL,'Finally, the pilot was able to land the balloon safely in a field. They managed to have the adventure of a lifetime — and no one got hurt.','最后,飞行员把气球安全地降落在一片田野里。他们经历了一生难忘的冒险——而且没有一个人受伤。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
