INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l91','be able to','',NULL,'/bi ˈeɪbl tu/','The pilot was able to land safely.','飞行员成功地安全降落了。','After years of study, she was able to read French.','学了多年后,她能读法语了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l91','manage to','',NULL,'/ˈmænɪdʒ tu/','He managed to turn the balloon around.','他设法让气球掉了头。','We managed to finish the work on time.','我们设法按时完成了工作。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l91','hot-air balloon','',NULL,'/hɑːt er bəˈluːn/','They joined a hot-air balloon ride.','他们坐了一次热气球。','A hot-air balloon floated over the valley.','一只热气球飘过山谷。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l91','of a lifetime','',NULL,'/əv ə ˈlaɪftaɪm/','They had the adventure of a lifetime.','他们经历了一生难忘的冒险。','It was the trip of a lifetime.','那是一生难忘的一次旅行。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp1','choice','{"stem":"\"Soon they ___ see the whole valley below them.\"(过去的能力:能够)","options":["could","manage to","can","are able"],"answer_index":0,"stem_cn":"不一会儿,他们就能俯瞰整片山谷。","explanation_cn":"过去的能力,用 could + 动词原形。✓ They could see the whole valley. ✗ can:一般现在;✗ manage to:意为“设法做成”,与“能看见”不符,且形式不对;✗ are able:一般现在且不完整。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp1','choice','{"stem":"\"''___ you all fit in the basket?'' the pilot asked.\"(问现在的能力:……吗)","options":["Could","Are","Can","Manage"],"answer_index":2,"stem_cn":"“你们都挤得进吊篮吗?”飞行员问。","explanation_cn":"问现在的能力“……吗”,用 Can 提到句首。✓ Can you all fit in the basket? ✗ Could:偏委婉/过去;✗ Manage:此处不能这样用;✗ Are:与原形 fit 不搭。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp1','choice','{"stem":"\"''Don''t worry — I ___ handle it,'' he said calmly.\"(现在的能力:能)","options":["can","could","am able","managed"],"answer_index":0,"stem_cn":"“别担心——我能应付,”他镇定地说。","explanation_cn":"现在的能力“能”,用 can + 原形。✓ I can handle it. ✗ could:偏委婉/过去;✗ managed:一般过去;✗ am able:后面缺 to,不完整。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp2','choice','{"stem":"\"Last summer, three friends ___ join a balloon ride.\"(去年那段时间能够做到)","options":["could to","can","are able to","were able to"],"answer_index":3,"stem_cn":"去年夏天,三个朋友坐上了一次热气球。","explanation_cn":"去年那段时间“能够做到”,用 were able to + 原形。✓ Three friends were able to join a balloon ride. ✗ can:一般现在;✗ could to:could 后不加 to;✗ are able to:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp2','choice','{"stem":"\"Finally, the pilot ___ land the balloon safely.\"(过去某一次成功做到了)","options":["was able to","is able to","could to","can"],"answer_index":0,"stem_cn":"最后,飞行员把气球安全地降落。","explanation_cn":"过去某一次“成功做到了”,用 was able to + 原形。✓ The pilot was able to land the balloon safely. ✗ can:一般现在;✗ could to:could 后不加 to;✗ is able to:一般现在。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp2','choice','{"stem":"\"None of them ___ see their town from the sky before.\"(在那之前一直未能做到——过去完成的能力形式)","options":["can","were able","had been able to","could"],"answer_index":2,"stem_cn":"他们谁都不曾从空中看过自己的镇子。","explanation_cn":"在那之前“一直未能做到”,用过去完成的能力形式 had been able to。✓ None of them had ever been able to see their town from the sky. ✗ could:不表“在那之前”;✗ can:一般现在;✗ were able:形式不完整。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp3','choice','{"stem":"\"After a tense minute, he ___ turn the balloon around.\"(费了一番劲设法做成)","options":["can","managed to","was able","could"],"answer_index":1,"stem_cn":"紧张了一分钟后,他设法让气球掉了头。","explanation_cn":"费了一番劲“设法做成”,用 managed to + 原形。✓ He managed to turn the balloon around. ✗ could:某一次成功做到不用 could;✗ can:一般现在;✗ was able:后面缺 to,不完整。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp3','choice','{"stem":"\"They ___ have the adventure of a lifetime.\"(设法做成、得以实现)","options":["would","can","managed to","could"],"answer_index":2,"stem_cn":"他们得以经历一生难忘的冒险。","explanation_cn":"“设法做成、得以实现”,用 managed to。✓ They managed to have the adventure of a lifetime. ✗ could:不表“设法做成这一次”;✗ can:一般现在;✗ would:意愿,不表“做成”。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp3','choice','{"stem":"\"In the strong wind, the pilot ___ keep the balloon steady.\"(费劲设法做到)","options":["could","can","will","managed to"],"answer_index":3,"stem_cn":"在大风里,飞行员设法让气球稳住了。","explanation_cn":"费劲“设法做到”,用 managed to。✓ The pilot managed to keep the balloon steady. ✗ could:某次做到不用 could;✗ can:一般现在;✗ will:将来。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp4','choice','{"stem":"\"But the wind was strong, and the pilot ___ steer easily.\"(过去不能)","options":["couldn''t","didn''t able","can''t","wasn''t able"],"answer_index":0,"stem_cn":"可风很大,飞行员没法轻松掌舵。","explanation_cn":"过去“不能、无法”,用 couldn''t。✓ The pilot couldn''t steer easily. ✗ can''t:一般现在;✗ didn''t able:错形；✗ wasn''t able:后面缺 to,不完整。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp4','choice','{"stem":"\"''I ___ believe how beautiful it is!'' one of them said.\"(现在不能:不敢相信)","options":["don''t able","can''t","couldn''t","am not able"],"answer_index":1,"stem_cn":"“真不敢相信有这么美!”其中一个人说。","explanation_cn":"现在“不能、不敢”,用 can''t。✓ I can''t believe how beautiful it is! ✗ couldn''t:过去;✗ don''t able:错形;✗ am not able:后面缺 to,不完整。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp4','choice','{"stem":"\"At first they ___ see anything through the clouds.\"(过去不能)","options":["aren''t able","can''t","don''t can","couldn''t"],"answer_index":3,"stem_cn":"起初他们透过云层什么也看不见。","explanation_cn":"过去“不能、看不见”,用 couldn''t。✓ At first they couldn''t see anything. ✗ can''t:一般现在;✗ aren''t able:一般现在且缺 to;✗ don''t can:错形。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp5','choice','{"stem":"\"The wind was strong, but he ___ turn the balloon around at last.\"(费劲后成功做到这一次)","options":["can","managed to","could to","could"],"answer_index":1,"stem_cn":"风很大,但他最终还是让气球掉了头。","explanation_cn":"费劲后“成功做到这一次”,用 managed to(此处不用 could)。✓ He managed to turn the balloon around at last. ✗ could:某次成功做到不用 could;✗ can:一般现在;✗ could to:错形。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp5','choice','{"stem":"\"She ___ swim when she was five.\"(小时候一贯具备的能力)","options":["did can","was able to manage","managed to","could"],"answer_index":3,"stem_cn":"她五岁时就会游泳了。","explanation_cn":"过去一贯具备的能力(会游泳),用 could。✓ She could swim when she was five. ✗ managed to:意为“某次费劲做成”,与“一贯会”不符;✗ was able to manage:啰嗦、不自然;✗ did can:错形。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp5','choice','{"stem":"\"''We ___ try!'' they said when asked to fit in the basket.\"(表示“能、愿意试试”)","options":["can","managed to","were able","could"],"answer_index":0,"stem_cn":"被问能不能挤进吊篮时,他们说“我们试试看!”","explanation_cn":"表示“能、愿意试试”,用 can。✓ We can try! ✗ could:偏委婉/过去;✗ managed to:一般过去且意为“做成”;✗ were able:过去且缺 to。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp6','choice','{"stem":"\"The three friends rode in the ___ of the balloon.\"(吊篮用哪个词)","options":["pocket","kitchen","garden","basket"],"answer_index":3,"stem_cn":"三个朋友坐在气球的吊篮里。","explanation_cn":"气球下面装人的“吊篮”是 basket。✓ rode in the basket of the balloon. ✗ kitchen:厨房;✗ pocket:口袋;✗ garden:花园。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp6','choice','{"stem":"\"The ___ steered the balloon carefully.\"(飞行员、驾驶员用哪个词)","options":["teacher","pilot","cook","farmer"],"answer_index":1,"stem_cn":"飞行员小心地操纵着气球。","explanation_cn":"驾驶气球、飞机的“飞行员、驾驶员”是 pilot。✓ The pilot steered the balloon. ✗ farmer:农民;✗ teacher:老师;✗ cook:厨师。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',5,'am2_l91_gp6','choice','{"stem":"\"From above, they saw the green ___ below.\"(山谷用哪个词)","options":["valley","window","ceiling","pocket"],"answer_index":0,"stem_cn":"从空中,他们看见下方绿色的山谷。","explanation_cn":"两山之间的“山谷”是 valley。✓ saw the green valley below. ✗ ceiling:天花板;✗ pocket:口袋;✗ window:窗户。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',6,NULL,'choice','{"stem":"美语里\"度假\"说:","options":["holiday","break-time","day-off","vacation"],"answer_index":3,"explanation_cn":"美语“度假、假期”说 vacation;英式说 holiday。✓ We took a summer vacation. 我们过了个暑假。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',6,NULL,'choice','{"stem":"美语里\"秋天\"说:","options":["fall","autumn","cool-season","harvest-time"],"answer_index":0,"explanation_cn":"美语“秋天”说 fall;英式说 autumn。✓ The leaves turn red in the fall. 秋天树叶变红。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',6,NULL,'choice','{"stem":"basket 的意思是:","options":["钟","桌子","帽子","篮子,吊篮"],"answer_index":3,"explanation_cn":"basket = 篮子;这里指气球的吊篮。✓ fit in the basket 挤进吊篮。\n顺带记:帽子 = hat;桌子 = table;钟 = clock."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',6,NULL,'choice','{"stem":"steer 的意思是:","options":["唱歌","睡觉","驾驶,掌舵","购买"],"answer_index":2,"explanation_cn":"steer = 驾驶、掌舵、操纵方向。✓ couldn''t steer easily 没法轻松掌舵。\n顺带记:睡觉 = sleep;唱歌 = sing;购买 = buy."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',6,NULL,'choice','{"stem":"adventure 的意思是:","options":["疾病","冒险,历险","会议","作业"],"answer_index":1,"explanation_cn":"adventure = 冒险、历险。✓ the adventure of a lifetime 一生难忘的冒险。\n顺带记:作业 = homework;会议 = meeting;疾病 = illness."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',6,NULL,'choice','{"stem":"tense 的意思是:","options":["快乐的","轻松的","紧张的","无聊的"],"answer_index":2,"explanation_cn":"tense = 紧张的。✓ after a tense minute 紧张的一分钟后。\n顺带记:轻松的 = relaxed;无聊的 = bored;快乐的 = happy."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',7,NULL,'cloze','{"stem":"第 1 空","context":"Last summer, three friends ___1___ join a balloon ride. Soon they ___2___ see the whole valley. The wind was strong, but the pilot ___3___ turn the balloon around. Finally, he ___4___ land it safely.","blank_no":1,"options":["were able to","can","could to","are able to"],"answer_index":0,"explanation_cn":"去年那段时间能够做到,用 were able to。✓ Three friends were able to join a balloon ride.\n✗ can:一般现在;✗ could to:错形;✗ are able to:一般现在。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',7,NULL,'cloze','{"stem":"第 2 空","context":"Last summer, three friends ___1___ join a balloon ride. Soon they ___2___ see the whole valley. The wind was strong, but the pilot ___3___ turn the balloon around. Finally, he ___4___ land it safely.","blank_no":2,"options":["could","can","manage to","are able"],"answer_index":0,"explanation_cn":"过去的能力,用 could。✓ Soon they could see the whole valley.\n✗ can:一般现在;✗ manage to:意为“设法做成”且形式不对;✗ are able:一般现在且不完整。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',7,NULL,'cloze','{"stem":"第 3 空","context":"Last summer, three friends ___1___ join a balloon ride. Soon they ___2___ see the whole valley. The wind was strong, but the pilot ___3___ turn the balloon around. Finally, he ___4___ land it safely.","blank_no":3,"options":["managed to","could","can","would"],"answer_index":0,"explanation_cn":"费劲设法做成,用 managed to。✓ The pilot managed to turn the balloon around.\n✗ could:某次做到不用 could;✗ can:一般现在;✗ would:意愿。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',7,NULL,'cloze','{"stem":"第 4 空","context":"Last summer, three friends ___1___ join a balloon ride. Soon they ___2___ see the whole valley. The wind was strong, but the pilot ___3___ turn the balloon around. Finally, he ___4___ land it safely.","blank_no":4,"options":["was able to","can","could to","is able to"],"answer_index":0,"explanation_cn":"过去某一次成功做到,用 was able to。✓ Finally, he was able to land it safely.\n✗ can:一般现在;✗ could to:错形;✗ is able to:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',8,NULL,'choice','{"stem":"What did the three friends do last summer?","options":["Joined a hot-air balloon ride","Sailed a boat","Rode horses","Climbed a mountain"],"answer_index":0,"explanation_cn":"课文说 Last summer, three friends were able to join a hot-air balloon ride。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',8,NULL,'choice','{"stem":"What made steering the balloon hard?","options":["The dark clouds","The cold air","The heavy rain","The strong wind"],"answer_index":3,"explanation_cn":"课文说 the wind was strong, and the pilot couldn''t steer easily。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',8,NULL,'choice','{"stem":"How did the ride end?","options":["The balloon crashed","They got lost","The pilot landed safely in a field","It started to rain"],"answer_index":2,"explanation_cn":"课文说 Finally, the pilot was able to land the balloon safely in a field。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',9,NULL,'choice','{"stem":"你想说\"最后飞行员安全地把气球降落在田野里\"(过去某一次成功做到,用 was able to):","options":["Finally, the pilot could land the balloon safely in a field.","Finally, the pilot can land the balloon safely in a field.","Finally, the pilot was able to land the balloon safely in a field.","Finally, the pilot could to land the balloon safely in a field."],"answer_index":2,"explanation_cn":"过去某一次成功做到,用 was able to + 原形。✓ Finally, the pilot was able to land the balloon safely in a field. 场合:说某次终于成功地做成了某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',9,NULL,'choice','{"stem":"你想说\"费了一番劲,他设法让气球掉了头\"(设法做成,用 managed to):","options":["After a tense minute, he was manage to turn the balloon around.","After a tense minute, he could turn the balloon around.","After a tense minute, he can turn the balloon around.","After a tense minute, he managed to turn the balloon around."],"answer_index":3,"explanation_cn":"费劲设法做成,用 managed to + 原形。✓ After a tense minute, he managed to turn the balloon around. 场合:强调经过努力才做成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',9,NULL,'choice','{"stem":"你想说\"他们谁都不曾从空中看过自己的镇子\"(过去完成的能力形式):","options":["None of them could ever see their town from the sky before.","None of them had ever been able to see their town from the sky before.","None of them had ever can see their town from the sky before.","None of them can ever see their town from the sky before."],"answer_index":1,"explanation_cn":"在那之前一直未能做到,用过去完成的能力形式 had been able to。✓ None of them had ever been able to see their town from the sky before. 场合:说“在那之前从未能……”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"basket 的意思是:","options":["钟","篮子,吊篮","帽子","桌子"],"answer_index":1,"explanation_cn":"basket = 篮子;气球的吊篮。✓ the basket of the balloon 气球的吊篮。\n顺带记:帽子 = hat;桌子 = table;钟 = clock."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"valley 的意思是:","options":["山谷","天花板","口袋","窗户"],"answer_index":0,"explanation_cn":"valley = 山谷。✓ the whole valley below 下方整片山谷。\n顺带记:天花板 = ceiling;口袋 = pocket;窗户 = window."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"\"Finally, the pilot ___ land it safely.\"(过去某一次成功做到)","options":["can","could to","is able to","was able to"],"answer_index":3,"stem_cn":"最后,飞行员把气球安全降落。","explanation_cn":"过去某一次成功做到,用 was able to。✓ Finally, the pilot was able to land it safely.\n✗ can:一般现在;✗ could to:错形;✗ is able to:一般现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"\"After a tense minute, he ___ turn it around.\"(费劲设法做成)","options":["could","would","managed to","can"],"answer_index":2,"stem_cn":"紧张了一分钟后,他设法让它掉了头。","explanation_cn":"费劲设法做成,用 managed to。✓ After a tense minute, he managed to turn it around.\n✗ could:某次做到不用 could;✗ can:一般现在;✗ would:意愿。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"\"manage to\" 的意思是:","options":["安排时间","打算做","管理某人","设法做到、费劲做成"],"answer_index":3,"explanation_cn":"manage to = 设法做到、费了劲做成。✓ He managed to turn the balloon around。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"\"be able to\" 的意思是:","options":["被允许做","能够、有能力做","愿意做","喜欢做"],"answer_index":1,"explanation_cn":"be able to = 能够、有能力做(可用于各种时态)。✓ The pilot was able to land safely。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"What could the friends see from the balloon?","options":["The whole valley below them","A big city","Nothing at all","The sea"],"answer_index":0,"passage":"Last summer, three friends were able to join a hot-air balloon ride. \"Can you all fit in the basket?\" the pilot asked. \"We can try!\" they said. Soon they could see the whole valley below them. But the wind was strong, and the pilot couldn''t steer easily. \"Don''t worry — I can handle it,\" he said calmly. After a tense minute, he managed to turn the balloon around. None of them had ever been able to see their town from the sky before. \"I can''t believe how beautiful it is!\" one of them said. Finally, the pilot was able to land the balloon safely in a field. They managed to have the adventure of a lifetime — and no one got hurt.","explanation_cn":"课文说 Soon they could see the whole valley below them。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"How did the balloon ride end?","options":["They landed in a lake","They landed safely and no one got hurt","The balloon was lost","Someone was hurt"],"answer_index":1,"passage":"Last summer, three friends were able to join a hot-air balloon ride. \"Can you all fit in the basket?\" the pilot asked. \"We can try!\" they said. Soon they could see the whole valley below them. But the wind was strong, and the pilot couldn''t steer easily. \"Don''t worry — I can handle it,\" he said calmly. After a tense minute, he managed to turn the balloon around. None of them had ever been able to see their town from the sky before. \"I can''t believe how beautiful it is!\" one of them said. Finally, the pilot was able to land the balloon safely in a field. They managed to have the adventure of a lifetime — and no one got hurt.","explanation_cn":"课文说 the pilot was able to land the balloon safely… and no one got hurt。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"What did the three friends join last summer?","options":["A hot-air balloon ride","A mountain climb","A boat trip","A horse race"],"answer_index":0,"audio":"Last summer, three friends were able to join a hot-air balloon ride. \"Can you all fit in the basket?\" the pilot asked. \"We can try!\" they said. Soon they could see the whole valley below them. But the wind was strong, and the pilot couldn''t steer easily. \"Don''t worry — I can handle it,\" he said calmly. After a tense minute, he managed to turn the balloon around. None of them had ever been able to see their town from the sky before. \"I can''t believe how beautiful it is!\" one of them said. Finally, the pilot was able to land the balloon safely in a field. They managed to have the adventure of a lifetime — and no one got hurt.","explanation_cn":"课文说 three friends were able to join a hot-air balloon ride。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l91',10,NULL,'choice','{"stem":"What made steering hard?","options":["The heavy rain","The thick fog","The strong wind","The cold"],"answer_index":2,"audio":"Last summer, three friends were able to join a hot-air balloon ride. \"Can you all fit in the basket?\" the pilot asked. \"We can try!\" they said. Soon they could see the whole valley below them. But the wind was strong, and the pilot couldn''t steer easily. \"Don''t worry — I can handle it,\" he said calmly. After a tense minute, he managed to turn the balloon around. None of them had ever been able to see their town from the sky before. \"I can''t believe how beautiful it is!\" one of them said. Finally, the pilot was able to land the balloon safely in a field. They managed to have the adventure of a lifetime — and no one got hurt.","explanation_cn":"课文说 the wind was strong, and the pilot couldn''t steer easily。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l92',2,12,92,'The Windows Need Cleaning','窗户该擦了','复习 KS20/44/68 need / want + 动名词的用法(收官包·干净课美语化):need + doing 与 want + doing 都表示“需要被……”,用主动的 -ing 形式表达被动的意思(need cleaning = need to be cleaned);对比 need + to do(主语主动去做)','“我觉得窗户不用擦吧,”爸爸看着窗户说。“其实真该擦了,”妈妈笑道,“上面全是灰。”“客人来之前,整间屋子都得收拾一下,”她又说。“地毯得用吸尘器吸一吸,花也该浇水了。”“花园也要拾掇吗?”我哼唧着问。“草是该剪了,”爸爸承认,“不过那个可以缓缓。”我们都同意厨房最该打扫。“我房间不用收拾,”弟弟嘴硬,没人信他。三个小时后,再没什么要做的了。“这屋子需要的可不只是打扫,”爸爸打趣道,“它需要好好歇一歇!”','{"q":"Listen and answer — What did Mom say about the windows?","options":["They need washing","They look perfectly clean","They should stay closed","They need replacing"],"answer_index":0}'::jsonb,'{"title":"复习 KS20/44/68 need / want + 动名词","intro":"本课复习一个特别的用法:need 和 want 后面接动名词(-ing)时,用主动的形式表达被动的意思,等于“需要被……”。①need + doing = need to be done(The windows need cleaning = 窗户需要被擦);②want + doing 同义(The grass wants cutting = 草需要被剪);③各种主语、时态都可以(The kitchen needed cleaning;My room doesn''t need tidying)。对比:need + to do 则是“主语主动去做某事”(You need to take a rest = 你需要去休息)。","table":{"headers":["用法","例子"],"rows":[["need + doing(= 需要被……)","The windows need cleaning."],["want + doing(同义)","The grass wants cutting."],["各主语 / 时态","The kitchen needed cleaning. / My room doesn''t need tidying."],["对比 need + to do","You need to take a rest.(主语主动去做)"]]},"specialRules":[{"rule":"美语“公寓”说 apartment(英式 flat);“垃圾”说 trash(英式 rubbish)。本课已按美语写。","mark":"apartment / trash"},{"rule":"need / want + doing 用主动的 -ing 表被动“需要被……”;need + to do 则是主语主动去做。别把 need cleaning 说成 need to clean(意思会变)。","mark":"doing vs to do"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l92',1,NULL,'"I don''t think the windows need cleaning," Dad said, looking at them. "Actually, they really need washing," Mom laughed. "They''re covered in dust."','“我觉得窗户不用擦吧,”爸爸看着窗户说。“其实真该擦了,”妈妈笑道,“上面全是灰。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l92',2,NULL,'"The whole house wants tidying before the guests come," she added. "The carpet needs vacuuming, and the plants need watering."','“客人来之前,整间屋子都得收拾一下,”她又说。“地毯得用吸尘器吸一吸,花也该浇水了。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l92',3,NULL,'"Does the garden need doing too?" I asked with a groan. "The grass wants cutting," Dad admitted, "but that can wait."','“花园也要拾掇吗?”我哼唧着问。“草是该剪了,”爸爸承认,“不过那个可以缓缓。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l92',4,NULL,'We all agreed the kitchen needed cleaning the most. "My room doesn''t need tidying," my brother claimed. Nobody believed him.','我们都同意厨房最该打扫。“我房间不用收拾,”弟弟嘴硬,没人信他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l92',5,NULL,'After three hours, nothing needed doing anymore. "The house needs more than cleaning," Dad joked. "It needs a rest!"','三个小时后,再没什么要做的了。“这屋子需要的可不只是打扫,”爸爸打趣道,“它需要好好歇一歇!”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
