INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l92','be covered in','',NULL,'/bi ˈkʌvərd ɪn/','The windows are covered in dust.','窗户上全是灰。','The desk was covered in books.','桌子上堆满了书。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l92','before the guests come','',NULL,'/bɪˈfɔːr ðə ɡests kʌm/','The house wants tidying before the guests come.','客人来之前屋子得收拾一下。','Let''s finish before the guests come.','咱们赶在客人来之前弄完吧。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l92','that can wait','',NULL,'/ðæt kæn weɪt/','The grass wants cutting, but that can wait.','草是该剪了,不过那个可以缓缓。','It''s not urgent — that can wait.','不急——那个可以缓缓。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l92','more than','',NULL,'/mɔːr ðæn/','The house needs more than cleaning.','这屋子需要的不只是打扫。','It cost more than I expected.','它比我预想的还要贵。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp1','choice','{"stem":"\"''I don''t think the windows need ___,'' Dad said.\"(need + 动名词,表“需要被擦”)","options":["clean","cleaning","to clean","cleaned"],"answer_index":1,"stem_cn":"“我觉得窗户不用擦吧,”爸爸说。","explanation_cn":"need 后接动名词(-ing),用主动形式表被动“需要被擦”。✓ The windows need cleaning. ✗ to clean:意思变成“需要去擦别的”;✗ cleaned:need 后不直接接过去分词;✗ clean:原形不表此意。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp1','choice','{"stem":"\"The carpet needs ___ — it''s very dusty.\"(need + 动名词)","options":["vacuuming","to vacuum","vacuumed","vacuum"],"answer_index":0,"stem_cn":"地毯得用吸尘器吸一吸——太脏了。","explanation_cn":"need + 动名词,表“需要被吸尘”。✓ The carpet needs vacuuming. ✗ to vacuum:意思会变;✗ vacuumed:need 后不直接接过去分词;✗ vacuum:原形不表此意。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp1','choice','{"stem":"\"The plants need ___ every day.\"(need + 动名词)","options":["water","watering","to water","watered"],"answer_index":1,"stem_cn":"花每天都需要浇水。","explanation_cn":"need + 动名词,表“需要被浇水”。✓ The plants need watering. ✗ to water:意思会变;✗ watered:need 后不直接接过去分词;✗ water:原形不表此意。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp2','choice','{"stem":"\"''The whole house wants ___ before the guests come,'' Mom said.\"(want + 动名词,表“需要被收拾”)","options":["tidy","to tidy","tidied","tidying"],"answer_index":3,"stem_cn":"“客人来之前,整间屋子都得收拾一下,”妈妈说。","explanation_cn":"want 后接动名词,同 need + doing,表“需要被收拾”。✓ The whole house wants tidying. ✗ to tidy:意思会变;✗ tidied:want 后不直接接过去分词;✗ tidy:原形不表此意。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp2','choice','{"stem":"\"''The grass wants ___,'' Dad admitted.\"(want + 动名词)","options":["to cut","cut","cutting","cuts"],"answer_index":2,"stem_cn":"“草是该剪了,”爸爸承认。","explanation_cn":"want + 动名词,表“需要被剪”。✓ The grass wants cutting. ✗ to cut:意思会变;✗ cut:原形不表此意;✗ cuts:第三人称形式不合。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp2','choice','{"stem":"\"These old shoes want ___; they''re really dirty.\"(want + 动名词)","options":["cleaning","to clean","clean","cleaned"],"answer_index":0,"stem_cn":"这双旧鞋该刷了,太脏了。","explanation_cn":"want + 动名词,表“需要被刷洗”。✓ These old shoes want cleaning. ✗ to clean:意思会变;✗ cleaned:want 后不直接接过去分词;✗ clean:原形不表此意。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp3','choice','{"stem":"\"''They really need ___,'' Mom laughed. ''They''re covered in dust.''\"(主动 -ing 表被动“需要被洗”)","options":["washed","washing","to wash","wash"],"answer_index":1,"stem_cn":"“它们真该洗了,”妈妈笑道,“上面全是灰。”","explanation_cn":"need + 动名词,用主动的 -ing 形式表被动“需要被洗”。✓ They really need washing. ✗ to wash:意思会变;✗ washed:need 后不直接接过去分词;✗ wash:原形不表此意。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp3','choice','{"stem":"\"The kitchen floor needs ___ after dinner.\"(主动 -ing 表被动)","options":["mop","to mop","mopping","mopped"],"answer_index":2,"stem_cn":"晚饭后厨房地板需要拖一拖。","explanation_cn":"need + 动名词,表“需要被拖”。✓ The kitchen floor needs mopping. ✗ to mop:意思会变;✗ mopped:need 后不直接接过去分词;✗ mop:原形不表此意。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp3','choice','{"stem":"\"That broken gate needs ___ soon.\"(主动 -ing 表被动)","options":["fix","fixing","fixed","to fix"],"answer_index":1,"stem_cn":"那扇坏了的门很快就得修了。","explanation_cn":"need + 动名词,表“需要被修”。✓ That broken gate needs fixing. ✗ to fix:意思会变;✗ fixed:need 后不直接接过去分词;✗ fix:原形不表此意。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp4','choice','{"stem":"\"We all agreed the kitchen ___ cleaning the most.\"(过去:need 的过去式 + 动名词)","options":["needing","need","needed","needs"],"answer_index":2,"stem_cn":"我们都同意厨房最该打扫。","explanation_cn":"过去“最该打扫”,用 need 的过去式 needed + 动名词。✓ The kitchen needed cleaning the most. ✗ need:主语单数用 needs,且此处是过去;✗ needs:一般现在;✗ needing:形式不合。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp4','choice','{"stem":"\"''My room doesn''t need ___,'' my brother claimed.\"(否定:doesn''t need + 动名词)","options":["to tidy","tidying","tidy","tidied"],"answer_index":1,"stem_cn":"“我房间不用收拾,”弟弟坚称。","explanation_cn":"否定“不用收拾”,用 doesn''t need + 动名词。✓ My room doesn''t need tidying. ✗ to tidy:意思会变;✗ tidied:need 后不直接接过去分词;✗ tidy:原形不表此意。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp4','choice','{"stem":"\"After three hours, nothing ___ doing anymore.\"(过去:need 的过去式)","options":["needed","needs","need","is needing"],"answer_index":0,"stem_cn":"三个小时后,再没什么要做的了。","explanation_cn":"过去“再没什么要做”,用 need 的过去式 needed。✓ Nothing needed doing anymore. ✗ need:此处是过去;✗ needs:一般现在;✗ is needing:need 一般不用进行时。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp5','choice','{"stem":"\"''Does the garden need ___ too?'' I asked.\"(疑问:need + 动名词)","options":["to do","doing","do","done"],"answer_index":1,"stem_cn":"“花园也要拾掇吗?”我问。","explanation_cn":"疑问句里 need + 动名词,表“需要被拾掇”。✓ Does the garden need doing too? ✗ to do:意思会变;✗ done:need 后不直接接过去分词;✗ do:原形不表此意。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp5','choice','{"stem":"\"You look tired. You need ___ a rest.\"(need + to do:你主动去做)","options":["taking","take","taken","to take"],"answer_index":3,"stem_cn":"你看着累了,你需要休息一下。","explanation_cn":"need 后接 to do,表示主语“主动去做”某事。✓ You need to take a rest. ✗ taking:此处是“你去休息”,不是“你需要被休息”;✗ take:缺 to;✗ taken:过去分词不合。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp5','choice','{"stem":"\"The car is dirty; it needs ___.\"(need + 动名词:需要被洗)","options":["wash","to wash","washing","washed"],"answer_index":2,"stem_cn":"车脏了,该洗了。","explanation_cn":"need + 动名词,表“需要被洗”。✓ The car needs washing. ✗ to wash:意思会变;✗ washed:need 后不直接接过去分词;✗ wash:原形不表此意。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp6','choice','{"stem":"\"The floor was covered in ___.\"(灰尘用哪个词)","options":["water","gold","snow","dust"],"answer_index":3,"stem_cn":"地板上落满了灰尘。","explanation_cn":"“灰尘”是 dust。✓ covered in dust. ✗ water:水;✗ gold:金子;✗ snow:雪。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp6','choice','{"stem":"\"Please ___ your room before the guests arrive.\"(整理、收拾用哪个词)","options":["tidy","drop","lose","break"],"answer_index":0,"stem_cn":"客人到之前请把你的房间收拾好。","explanation_cn":"“整理、收拾”是 tidy。✓ tidy your room. ✗ break:打碎;✗ lose:丢失;✗ drop:掉落。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',5,'am2_l92_gp6','choice','{"stem":"\"The visitors are our ___ tonight.\"(客人用哪个词)","options":["drivers","doctors","teachers","guests"],"answer_index":3,"stem_cn":"今晚这些来访者是我们的客人。","explanation_cn":"来访的“客人”是 guest(复数 guests)。✓ our guests tonight. ✗ teachers:老师;✗ drivers:司机;✗ doctors:医生。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',6,NULL,'choice','{"stem":"美语里\"公寓\"说:","options":["room-set","apartment","house-unit","flat"],"answer_index":1,"explanation_cn":"美语“公寓”说 apartment;英式说 flat。✓ They live in a small apartment. 他们住在一间小公寓里。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',6,NULL,'choice','{"stem":"美语里\"垃圾\"说:","options":["trash","rubbish","litter-box","waste-bin"],"answer_index":0,"explanation_cn":"美语“垃圾”说 trash;英式说 rubbish。✓ Take out the trash, please. 请把垃圾拿出去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',6,NULL,'choice','{"stem":"dust 的意思是:","options":["水","花","石头","灰尘"],"answer_index":3,"explanation_cn":"dust = 灰尘。✓ covered in dust 满是灰尘。\n顺带记:水 = water;花 = flower;石头 = stone."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',6,NULL,'choice','{"stem":"tidy 的意思是:","options":["打碎","弄乱","整理,收拾","丢弃"],"answer_index":2,"explanation_cn":"tidy = 整理、收拾。✓ tidy the room 收拾房间。\n顺带记:弄乱 = mess up;打碎 = break;丢弃 = throw away."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',6,NULL,'choice','{"stem":"guest 的意思是:","options":["主人","邻居","陌生人","客人"],"answer_index":3,"explanation_cn":"guest = 客人。✓ before the guests come 客人来之前。\n顺带记:主人 = host;邻居 = neighbor;陌生人 = stranger."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',6,NULL,'choice','{"stem":"vacuum 的意思是:","options":["洗涤","做饭","用吸尘器打扫","浇水"],"answer_index":2,"explanation_cn":"vacuum = 用吸尘器打扫。✓ the carpet needs vacuuming 地毯需要吸尘。\n顺带记:浇水 = water;做饭 = cook;洗涤 = wash."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',7,NULL,'cloze','{"stem":"第 1 空","context":"\"The windows need ___1___,\" Mom said. \"The carpet needs ___2___ too.\" \"Does the garden need ___3___?\" I asked. We all agreed the kitchen ___4___ cleaning the most.","blank_no":1,"options":["washing","to wash","washed","wash"],"answer_index":0,"explanation_cn":"need + 动名词,表“需要被洗”。✓ The windows need washing.\n✗ to wash:意思会变;✗ washed:need 后不直接接过去分词;✗ wash:原形不表此意。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',7,NULL,'cloze','{"stem":"第 2 空","context":"\"The windows need ___1___,\" Mom said. \"The carpet needs ___2___ too.\" \"Does the garden need ___3___?\" I asked. We all agreed the kitchen ___4___ cleaning the most.","blank_no":2,"options":["vacuuming","to vacuum","vacuumed","vacuum"],"answer_index":0,"explanation_cn":"need + 动名词,表“需要被吸尘”。✓ The carpet needs vacuuming.\n✗ to vacuum:意思会变;✗ vacuumed / vacuum:形式不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',7,NULL,'cloze','{"stem":"第 3 空","context":"\"The windows need ___1___,\" Mom said. \"The carpet needs ___2___ too.\" \"Does the garden need ___3___?\" I asked. We all agreed the kitchen ___4___ cleaning the most.","blank_no":3,"options":["doing","to do","done","do"],"answer_index":0,"explanation_cn":"疑问句里 need + 动名词。✓ Does the garden need doing?\n✗ to do:意思会变;✗ done / do:形式不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',7,NULL,'cloze','{"stem":"第 4 空","context":"\"The windows need ___1___,\" Mom said. \"The carpet needs ___2___ too.\" \"Does the garden need ___3___?\" I asked. We all agreed the kitchen ___4___ cleaning the most.","blank_no":4,"options":["needed","need","needs","needing"],"answer_index":0,"explanation_cn":"过去“最该打扫”,用 needed。✓ The kitchen needed cleaning the most.\n✗ need:主语单数且此处过去;✗ needs:一般现在;✗ needing:形式不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',8,NULL,'choice','{"stem":"What did Mom say about the windows?","options":["They are broken","They need washing","They need painting","They look clean"],"answer_index":1,"explanation_cn":"课文说 \"Actually, they really need washing,\" Mom laughed。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',8,NULL,'choice','{"stem":"What did Dad admit wanted cutting?","options":["His hair","The bread","The grass","The rope"],"answer_index":2,"explanation_cn":"课文说 \"The grass wants cutting,\" Dad admitted。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',8,NULL,'choice','{"stem":"What did everyone agree needed cleaning the most?","options":["The kitchen","The attic","The garden","The car"],"answer_index":0,"explanation_cn":"课文说 We all agreed the kitchen needed cleaning the most。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',9,NULL,'choice','{"stem":"你想说\"窗户该擦了\"(need + 动名词,主动形式表被动):","options":["The windows need cleaning.","The windows needs cleaning.","The windows need to cleaning.","The windows need clean."],"answer_index":0,"explanation_cn":"need 后接动名词,用主动形式表被动“需要被擦”。✓ The windows need cleaning. 场合:说某物“需要被……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',9,NULL,'choice','{"stem":"你想说\"客人来之前整间屋子都得收拾\"(want + 动名词):","options":["The whole house wants tidy before the guests come.","The whole house wants to tidying before the guests come.","The whole house wants tidying before the guests come.","The whole house want tidying before the guests come."],"answer_index":2,"explanation_cn":"want 后接动名词,同 need + doing,表“需要被收拾”。✓ The whole house wants tidying before the guests come. 场合:说某处需要被打理。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',9,NULL,'choice','{"stem":"你想说\"地毯需要用吸尘器吸一吸\"(need + 动名词):","options":["The carpet need vacuuming.","The carpet needs to vacuuming.","The carpet needs vacuumed.","The carpet needs vacuuming."],"answer_index":3,"explanation_cn":"need + 动名词,表“需要被吸尘”。✓ The carpet needs vacuuming. 场合:说某物需要被清理。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"dust 的意思是:","options":["石头","灰尘","花","水"],"answer_index":1,"explanation_cn":"dust = 灰尘。✓ covered in dust 满是灰尘。\n顺带记:水 = water;花 = flower;石头 = stone."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"guest 的意思是:","options":["邻居","陌生人","主人","客人"],"answer_index":3,"explanation_cn":"guest = 客人。✓ before the guests come 客人来之前。\n顺带记:主人 = host;邻居 = neighbor;陌生人 = stranger."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"\"The windows need ___.\"(need + 动名词,表“需要被擦”)","options":["clean","cleaning","to clean","cleaned"],"answer_index":1,"stem_cn":"窗户该擦了。","explanation_cn":"need + 动名词,表“需要被擦”。✓ The windows need cleaning.\n✗ to clean:意思会变;✗ cleaned:need 后不直接接过去分词;✗ clean:原形不表此意。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"\"The whole house wants ___ before the guests come.\"(want + 动名词)","options":["to tidy","tidied","tidying","tidy"],"answer_index":2,"stem_cn":"客人来之前整间屋子都得收拾。","explanation_cn":"want + 动名词,表“需要被收拾”。✓ The whole house wants tidying.\n✗ to tidy:意思会变;✗ tidied / tidy:形式不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"\"need cleaning\" 的意思是:","options":["需要(被)清洗","喜欢清洗","刚清洗过","需要去清洗别的"],"answer_index":0,"explanation_cn":"need cleaning = 需要(被)清洗(主动的 -ing 形式表被动的意思)。✓ The windows need cleaning。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"\"be covered in\" 的意思是:","options":["藏在……下面","属于……","布满、覆盖着","远离……"],"answer_index":2,"explanation_cn":"be covered in = 布满、覆盖着。✓ The windows are covered in dust。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"What did Mom say about the windows?","options":["They need new glass","They really need washing","They are already clean","They should stay shut"],"answer_index":1,"passage":"\"I don''t think the windows need cleaning,\" Dad said, looking at them. \"Actually, they really need washing,\" Mom laughed. \"They''re covered in dust.\" \"The whole house wants tidying before the guests come,\" she added. \"The carpet needs vacuuming, and the plants need watering.\" \"Does the garden need doing too?\" I asked with a groan. \"The grass wants cutting,\" Dad admitted, \"but that can wait.\" We all agreed the kitchen needed cleaning the most. \"My room doesn''t need tidying,\" my brother claimed. Nobody believed him. After three hours, nothing needed doing anymore. \"The house needs more than cleaning,\" Dad joked. \"It needs a rest!\"","explanation_cn":"课文说 \"Actually, they really need washing,\" Mom laughed。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"What did the brother claim?","options":["He was too tired","The windows were fine","He would clean the kitchen","His room didn''t need tidying"],"answer_index":3,"passage":"\"I don''t think the windows need cleaning,\" Dad said, looking at them. \"Actually, they really need washing,\" Mom laughed. \"They''re covered in dust.\" \"The whole house wants tidying before the guests come,\" she added. \"The carpet needs vacuuming, and the plants need watering.\" \"Does the garden need doing too?\" I asked with a groan. \"The grass wants cutting,\" Dad admitted, \"but that can wait.\" We all agreed the kitchen needed cleaning the most. \"My room doesn''t need tidying,\" my brother claimed. Nobody believed him. After three hours, nothing needed doing anymore. \"The house needs more than cleaning,\" Dad joked. \"It needs a rest!\"","explanation_cn":"课文说 \"My room doesn''t need tidying,\" my brother claimed。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"What did Dad say wanted cutting?","options":["The bread","The grass","The paper","The rope"],"answer_index":1,"audio":"\"I don''t think the windows need cleaning,\" Dad said, looking at them. \"Actually, they really need washing,\" Mom laughed. \"They''re covered in dust.\" \"The whole house wants tidying before the guests come,\" she added. \"The carpet needs vacuuming, and the plants need watering.\" \"Does the garden need doing too?\" I asked with a groan. \"The grass wants cutting,\" Dad admitted, \"but that can wait.\" We all agreed the kitchen needed cleaning the most. \"My room doesn''t need tidying,\" my brother claimed. Nobody believed him. After three hours, nothing needed doing anymore. \"The house needs more than cleaning,\" Dad joked. \"It needs a rest!\"","explanation_cn":"课文说 \"The grass wants cutting,\" Dad admitted。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l92',10,NULL,'choice','{"stem":"What needed cleaning the most?","options":["The car","The garden","The kitchen","The attic"],"answer_index":2,"audio":"\"I don''t think the windows need cleaning,\" Dad said, looking at them. \"Actually, they really need washing,\" Mom laughed. \"They''re covered in dust.\" \"The whole house wants tidying before the guests come,\" she added. \"The carpet needs vacuuming, and the plants need watering.\" \"Does the garden need doing too?\" I asked with a groan. \"The grass wants cutting,\" Dad admitted, \"but that can wait.\" We all agreed the kitchen needed cleaning the most. \"My room doesn''t need tidying,\" my brother claimed. Nobody believed him. After three hours, nothing needed doing anymore. \"The house needs more than cleaning,\" Dad joked. \"It needs a rest!\"","explanation_cn":"课文说 We all agreed the kitchen needed cleaning the most。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l93',2,12,93,'A Generous Gift','一份慷慨的礼物','复习 KS21/45/69 被动语态各时态综合(收官包·换道具照搬结构):一般现在/一般过去被动(is admired / was given)、现在完成被动(has been kept)、将来被动(will be moved)、现在进行被动(is being built)、情态被动(can be enjoyed / should be treasured),以及被动句中用 by 引出动作的发出者','很久以前,一位著名的艺术家把一座漂亮的老钟赠给了我们镇。这座钟完全是手工制作的,人人见了都赞叹不已。多年来,它一直摆在市政厅的正门口。每天早上,看管人都会细心地给它上发条。最近,城里来的一位专家为它做了修复。“这座钟被一代又一代人珍爱着,”市长说。不久,它就会被搬到新图书馆,让更多人能欣赏到它。一个特制的展柜正在打造中,用来保护它。它将被陈列在孩子们能了解它历史的地方。这样一份礼物理应被珍藏——而它也一定会被珍藏下去。','{"q":"Listen and answer — How was the old clock made?","options":["Entirely by hand","By a big machine","In a modern factory","From cheap plastic"],"answer_index":0}'::jsonb,'{"title":"复习 KS21/45/69 被动语态各时态","intro":"被动语态由 be + 过去分词构成,表示“被……”。本课把各时态的被动放在一起复习:①一般现在/一般过去被动——is admired / was given;②现在完成被动——has been kept(一直被……);③将来被动——will be moved;④现在进行被动——is being built(正在被……);⑤情态被动——can be enjoyed / should be treasured。被动句里若要说“由谁做的”,用 by 引出(was repaired by an expert)。","table":{"headers":["时态(被动)","例子"],"rows":[["一般现在 / 一般过去","It is admired by everyone. / It was given long ago."],["现在完成","It has been kept in the town hall for years."],["将来","Soon it will be moved to the new library."],["现在进行","A special case is being built to protect it."],["情态 / by 短语","It should be treasured. / It was repaired by an expert."]]},"specialRules":[{"rule":"美语“电梯”说 elevator(英式 lift);“一楼”说 first floor(英式 ground floor)。本课已按美语写。","mark":"elevator / first floor"},{"rule":"被动 = be 的相应时态 + 过去分词;现在进行被动是 is/are being + 过去分词;情态被动是 can/should + be + 过去分词;“由谁做”用 by 引出。","mark":"被动构成"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l93',1,NULL,'A beautiful old clock was given to our town by a famous artist long ago. It was made entirely by hand and is admired by everyone who sees it.','很久以前,一位著名的艺术家把一座漂亮的老钟赠给了我们镇。这座钟完全是手工制作的,人人见了都赞叹不已。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l93',2,NULL,'For years it has been kept in the town hall''s main entrance. Every morning it is wound carefully by the caretaker.','多年来,它一直摆在市政厅的正门口。每天早上,看管人都会细心地给它上发条。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l93',3,NULL,'Recently it was repaired by an expert from the city. "This clock has been loved for generations," the mayor said.','最近,城里来的一位专家为它做了修复。“这座钟被一代又一代人珍爱着,”市长说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l93',4,NULL,'Soon it will be moved to the new library so more people can enjoy it. A special case is being built to protect it.','不久,它就会被搬到新图书馆,让更多人能欣赏到它。一个特制的展柜正在打造中,用来保护它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l93',5,NULL,'It will be displayed where children can learn its history. Such a gift should be treasured, and it always will be.','它将被陈列在孩子们能了解它历史的地方。这样一份礼物理应被珍藏——而它也一定会被珍藏下去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
