INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l93','by hand','',NULL,'/baɪ hænd/','The clock was made entirely by hand.','这座钟完全是手工制作的。','She sews all her clothes by hand.','她所有衣服都是手工缝的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l93','town hall','',NULL,'/taʊn hɔːl/','It has been kept in the town hall for years.','它多年来一直放在市政厅。','The meeting was held at the town hall.','会议在市政厅召开。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l93','for generations','',NULL,'/fɔːr ˌdʒenəˈreɪʃnz/','This clock has been loved for generations.','这座钟被一代又一代人珍爱着。','The story has been told for generations.','这个故事世代相传。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l93','on display','',NULL,'/ɑːn dɪˈspleɪ/','The clock will be on display in the library.','这座钟将在图书馆里展出。','The paintings are on display this week.','这些画本周展出。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp1','choice','{"stem":"\"A beautiful old clock ___ to our town long ago.\"(一般过去被动:被赠予)","options":["was given","has given","gave","is given"],"answer_index":0,"stem_cn":"很久以前,一座漂亮的老钟被赠给了我们镇。","explanation_cn":"过去“被赠予”,用一般过去被动 was + 过去分词。✓ A clock was given to our town long ago. ✗ gave:主动;✗ is given:一般现在被动,与 long ago 不符;✗ has given:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp1','choice','{"stem":"\"It ___ by everyone who sees it.\"(一般现在被动:被赞赏)","options":["is admiring","admires","was admired","is admired"],"answer_index":3,"stem_cn":"人人见了它都赞叹不已。","explanation_cn":"经常性地“被赞赏”,用一般现在被动 is + 过去分词。✓ It is admired by everyone. ✗ admires:主动;✗ was admired:一般过去;✗ is admiring:进行主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp1','choice','{"stem":"\"It ___ entirely by hand.\"(一般过去被动:被制作)","options":["is making","was made","is made","made"],"answer_index":1,"stem_cn":"它完全是手工制作的。","explanation_cn":"过去“被制作”,用一般过去被动。✓ It was made entirely by hand. ✗ made:主动;✗ is made:一般现在被动,与“很久以前造的”不符;✗ is making:进行主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp2','choice','{"stem":"\"For years it ___ in the town hall''s entrance.\"(现在完成被动:一直被保存)","options":["was keeping","has kept","is kept","has been kept"],"answer_index":3,"stem_cn":"多年来它一直摆在市政厅的门口。","explanation_cn":"“多年来一直被保存”,用现在完成被动 has been + 过去分词。✓ It has been kept in the town hall for years. ✗ has kept:现在完成主动;✗ is kept:一般现在被动,不表“一直”;✗ was keeping:过去进行主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp2','choice','{"stem":"\"''This clock ___ for generations,'' the mayor said.\"(现在完成被动:一直被珍爱)","options":["has been loved","is loved","was loving","has loved"],"answer_index":0,"stem_cn":"“这座钟被一代又一代人珍爱着,”市长说。","explanation_cn":"“一直被珍爱”,用现在完成被动。✓ This clock has been loved for generations. ✗ has loved:现在完成主动;✗ is loved:一般现在被动;✗ was loving:过去进行主动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp2','choice','{"stem":"\"It ___ by more than a hundred visitors this month.\"(现在完成被动:已被看过)","options":["saw","has been seen","is seeing","has seen"],"answer_index":1,"stem_cn":"这个月它已被一百多名参观者看过。","explanation_cn":"“已被看过”,用现在完成被动。✓ It has been seen by more than a hundred visitors this month. ✗ has seen:现在完成主动;✗ is seeing:进行主动;✗ saw:一般过去主动。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp3','choice','{"stem":"\"Soon it ___ to the new library.\"(将来被动:将被搬)","options":["will be moved","will move","is moved","has moved"],"answer_index":0,"stem_cn":"不久它就会被搬到新图书馆。","explanation_cn":"将来“被搬”,用将来被动 will be + 过去分词。✓ Soon it will be moved to the library. ✗ will move:将来主动;✗ is moved:一般现在被动;✗ has moved:现在完成主动。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp3','choice','{"stem":"\"It ___ where children can learn its history.\"(将来被动:将被陈列)","options":["will display","is displaying","will be displayed","displayed"],"answer_index":2,"stem_cn":"它将被陈列在孩子们能了解它历史的地方。","explanation_cn":"将来“被陈列”,用将来被动。✓ It will be displayed for children. ✗ will display:将来主动;✗ is displaying:进行主动;✗ displayed:一般过去。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp3','choice','{"stem":"\"Next week the clock ___ to a safe place.\"(将来被动:将被送)","options":["took","is taking","will take","will be taken"],"answer_index":3,"stem_cn":"下周这座钟将被送到一个安全的地方。","explanation_cn":"将来“被送”,用将来被动。✓ Next week the clock will be taken to a safe place. ✗ will take:将来主动;✗ is taking:进行主动;✗ took:一般过去。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp4','choice','{"stem":"\"A special case ___ to protect it.\"(现在进行被动:正在被建造)","options":["builds","is being built","has built","is building"],"answer_index":1,"stem_cn":"一个特制的展柜正在打造中,用来保护它。","explanation_cn":"此刻“正在被建造”,用现在进行被动 is being + 过去分词。✓ A special case is being built. ✗ is building:进行主动;✗ builds:一般现在主动;✗ has built:现在完成主动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp4','choice','{"stem":"\"Right now, the old clock ___ by an expert.\"(现在进行被动:正在被检查)","options":["examines","is examining","is being examined","examined"],"answer_index":2,"stem_cn":"此刻,这座老钟正被一位专家检查。","explanation_cn":"此刻“正在被检查”,用现在进行被动。✓ The old clock is being examined by an expert. ✗ is examining:进行主动;✗ examines:一般现在主动;✗ examined:一般过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp4','choice','{"stem":"\"The hall ___ for the ceremony at the moment.\"(现在进行被动:正在被布置)","options":["decorates","decorated","is decorating","is being decorated"],"answer_index":3,"stem_cn":"此刻大厅正为典礼做布置。","explanation_cn":"此刻“正在被布置”,用现在进行被动。✓ The hall is being decorated for the ceremony. ✗ is decorating:进行主动;✗ decorates:一般现在主动;✗ decorated:一般过去。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp5','choice','{"stem":"\"Such a gift ___.\"(情态被动:理应被珍藏)","options":["is treasuring","treasures","should be treasured","should treasure"],"answer_index":2,"stem_cn":"这样一份礼物理应被珍藏。","explanation_cn":"情态“理应被珍藏”,用 should + be + 过去分词。✓ Such a gift should be treasured. ✗ should treasure:主动;✗ treasures:一般现在主动;✗ is treasuring:进行主动。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp5','choice','{"stem":"\"The clock will be placed where it ___ by all.\"(情态被动:能被欣赏)","options":["can enjoy","can be enjoyed","is enjoying","enjoys"],"answer_index":1,"stem_cn":"这座钟将被摆放在人人都能欣赏到它的地方。","explanation_cn":"情态“能被欣赏”,用 can + be + 过去分词。✓ where it can be enjoyed by all. ✗ can enjoy:主动;✗ enjoys:一般现在主动;✗ is enjoying:进行主动。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp5','choice','{"stem":"\"The clock was repaired ___ an expert from the city.\"(被动句里引出“由谁做”)","options":["by","with","for","of"],"answer_index":0,"stem_cn":"这座钟由城里来的一位专家修复。","explanation_cn":"被动句里引出“由谁做”,用 by。✓ It was repaired by an expert from the city. ✗ with:表用什么工具/材料;✗ for:为了;✗ of:属于。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp6','choice','{"stem":"\"The clock was a ___ gift from a kind artist.\"(慷慨的用哪个词)","options":["angry","tiny","generous","lazy"],"answer_index":2,"stem_cn":"这座钟是一位好心艺术家慷慨的馈赠。","explanation_cn":"“慷慨的、大方的”是 generous。✓ a generous gift. ✗ angry:生气的;✗ lazy:懒惰的;✗ tiny:极小的。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp6','choice','{"stem":"\"Every morning the ___ winds the clock carefully.\"(看管人用哪个词)","options":["pilot","caretaker","farmer","singer"],"answer_index":1,"stem_cn":"每天早上,看管人都细心地给钟上发条。","explanation_cn":"负责看管的“看管人、管理员”是 caretaker。✓ wound by the caretaker. ✗ singer:歌手;✗ pilot:飞行员;✗ farmer:农民。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',5,'am2_l93_gp6','choice','{"stem":"\"The ___ of the town gave a speech about the clock.\"(市长用哪个词)","options":["mayor","driver","guard","cook"],"answer_index":0,"stem_cn":"镇长为这座钟发表了讲话。","explanation_cn":"一镇之长“市长、镇长”是 mayor。✓ The mayor gave a speech. ✗ cook:厨师;✗ driver:司机;✗ guard:门卫。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',6,NULL,'choice','{"stem":"美语里\"电梯\"说:","options":["elevator","lift","riser","mover"],"answer_index":0,"explanation_cn":"美语“电梯”说 elevator;英式说 lift。✓ Take the elevator to the top floor. 乘电梯到顶层。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',6,NULL,'choice','{"stem":"美语里\"一楼\"说:","options":["base-floor","ground floor","first floor","level-one"],"answer_index":2,"explanation_cn":"美语“一楼”说 first floor;英式说 ground floor。✓ The clock is on the first floor. 钟在一楼。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',6,NULL,'choice','{"stem":"generous 的意思是:","options":["疲惫的","害怕的","吝啬的","慷慨的"],"answer_index":3,"explanation_cn":"generous = 慷慨的、大方的。✓ a generous gift 一份慷慨的礼物。\n顺带记:吝啬的 = mean;害怕的 = afraid;疲惫的 = tired."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',6,NULL,'choice','{"stem":"admire 的意思是:","options":["破坏","忽视","赞赏,钦佩","讨厌"],"answer_index":2,"explanation_cn":"admire = 赞赏、钦佩。✓ is admired by everyone 人人赞赏。\n顺带记:讨厌 = dislike;忽视 = ignore;破坏 = damage."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',6,NULL,'choice','{"stem":"treasure 的意思是:","options":["出售","珍惜,珍藏","遗忘","丢弃"],"answer_index":1,"explanation_cn":"treasure = 珍惜、珍藏。✓ should be treasured 理应被珍藏。\n顺带记:丢弃 = throw away;出售 = sell;遗忘 = forget."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',6,NULL,'choice','{"stem":"entirely 的意思是:","options":["完全地","几乎不","偶尔地","部分地"],"answer_index":0,"explanation_cn":"entirely = 完全地。✓ made entirely by hand 完全手工制作。\n顺带记:部分地 = partly;偶尔地 = sometimes;几乎不 = hardly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',7,NULL,'cloze','{"stem":"第 1 空","context":"A beautiful old clock ___1___ to our town long ago. For years it ___2___ in the town hall. Now a special case ___3___ to protect it. Soon it ___4___ to the new library.","blank_no":1,"options":["was given","gave","is given","has given"],"answer_index":0,"explanation_cn":"过去“被赠予”,用一般过去被动。✓ A beautiful old clock was given to our town long ago.\n✗ gave:主动;✗ is given:一般现在;✗ has given:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',7,NULL,'cloze','{"stem":"第 2 空","context":"A beautiful old clock ___1___ to our town long ago. For years it ___2___ in the town hall. Now a special case ___3___ to protect it. Soon it ___4___ to the new library.","blank_no":2,"options":["has been kept","has kept","is kept","kept"],"answer_index":0,"explanation_cn":"“多年来一直被保存”,用现在完成被动。✓ For years it has been kept in the town hall.\n✗ has kept:现在完成主动;✗ is kept:一般现在被动;✗ kept:一般过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',7,NULL,'cloze','{"stem":"第 3 空","context":"A beautiful old clock ___1___ to our town long ago. For years it ___2___ in the town hall. Now a special case ___3___ to protect it. Soon it ___4___ to the new library.","blank_no":3,"options":["is being built","is building","builds","built"],"answer_index":0,"explanation_cn":"此刻“正在被建造”,用现在进行被动。✓ A special case is being built to protect it.\n✗ is building:进行主动;✗ builds:一般现在主动;✗ built:一般过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',7,NULL,'cloze','{"stem":"第 4 空","context":"A beautiful old clock ___1___ to our town long ago. For years it ___2___ in the town hall. Now a special case ___3___ to protect it. Soon it ___4___ to the new library.","blank_no":4,"options":["will be moved","will move","is moved","moved"],"answer_index":0,"explanation_cn":"将来“被搬”,用将来被动。✓ Soon it will be moved to the new library.\n✗ will move:将来主动;✗ is moved:一般现在被动;✗ moved:一般过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',8,NULL,'choice','{"stem":"How was the old clock made?","options":["Entirely by hand","From plastic","In a factory","By a machine"],"answer_index":0,"explanation_cn":"课文说 It was made entirely by hand。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',8,NULL,'choice','{"stem":"Where has the clock been kept for years?","options":["In a school","In a private home","In the town hall''s main entrance","In a garden"],"answer_index":2,"explanation_cn":"课文说 For years it has been kept in the town hall''s main entrance。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',8,NULL,'choice','{"stem":"Where will the clock be moved soon?","options":["To a museum abroad","To the new library","Back to the artist","To another town"],"answer_index":1,"explanation_cn":"课文说 Soon it will be moved to the new library。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',9,NULL,'choice','{"stem":"你想说\"这只钟很久以前被一位著名艺术家赠给了我们镇\"(一般过去被动):","options":["A beautiful old clock is given to our town by a famous artist.","A beautiful old clock was given to our town by a famous artist.","A beautiful old clock has given to our town by a famous artist.","A beautiful old clock gave to our town by a famous artist."],"answer_index":1,"explanation_cn":"过去“被赠予”,用一般过去被动 was + 过去分词,by 引出赠予者。✓ A beautiful old clock was given to our town by a famous artist. 场合:说某物在过去被(某人)赠予。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',9,NULL,'choice','{"stem":"你想说\"多年来它一直被保存在市政厅\"(现在完成被动):","options":["For years it is kept in the town hall.","For years it has kept in the town hall.","For years it has been kept in the town hall.","For years it was keeping in the town hall."],"answer_index":2,"explanation_cn":"“多年来一直被保存”,用现在完成被动 has been + 过去分词。✓ For years it has been kept in the town hall. 场合:说某物一直被保存至今。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',9,NULL,'choice','{"stem":"你想说\"一个特制的展柜正在被打造来保护它\"(现在进行被动):","options":["A special case has built to protect it.","A special case builds to protect it.","A special case is building to protect it.","A special case is being built to protect it."],"answer_index":3,"explanation_cn":"此刻“正在被建造”,用现在进行被动 is being + 过去分词。✓ A special case is being built to protect it. 场合:说某物此刻正被制作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"generous 的意思是:","options":["害怕的","疲惫的","慷慨的","吝啬的"],"answer_index":2,"explanation_cn":"generous = 慷慨的。✓ a generous gift 一份慷慨的礼物。\n顺带记:吝啬的 = mean;害怕的 = afraid;疲惫的 = tired."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"mayor 的意思是:","options":["市长","司机","厨师","门卫"],"answer_index":0,"explanation_cn":"mayor = 市长、镇长。✓ the mayor said 市长说。\n顺带记:厨师 = cook;司机 = driver;门卫 = guard."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"\"It ___ by everyone who sees it.\"(一般现在被动)","options":["was admired","is admired","is admiring","admires"],"answer_index":1,"stem_cn":"人人见了它都赞叹。","explanation_cn":"经常性地“被赞赏”,用一般现在被动。✓ It is admired by everyone who sees it.\n✗ admires:主动;✗ was admired:一般过去;✗ is admiring:进行主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"\"Soon it ___ to the new library.\"(将来被动)","options":["will move","has moved","will be moved","is moved"],"answer_index":2,"stem_cn":"不久它就会被搬到新图书馆。","explanation_cn":"将来“被搬”,用将来被动。✓ Soon it will be moved to the new library.\n✗ will move:将来主动;✗ is moved:一般现在被动;✗ has moved:现在完成主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"\"by hand\" 的意思是:","options":["手工地","在手边","用手指着","亲手交给"],"answer_index":0,"explanation_cn":"by hand = 手工地(靠手工而非机器)。✓ made entirely by hand 完全手工制作。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"\"for generations\" 的意思是:","options":["一代人的时间","世世代代地","过了几年","为了发电"],"answer_index":1,"explanation_cn":"for generations = 世世代代地、一代又一代。✓ has been loved for generations 被世代珍爱。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"How was the clock made?","options":["In a hurry","From gold","By a machine","Entirely by hand"],"answer_index":3,"passage":"A beautiful old clock was given to our town by a famous artist long ago. It was made entirely by hand and is admired by everyone who sees it. For years it has been kept in the town hall''s main entrance. Every morning it is wound carefully by the caretaker. Recently it was repaired by an expert from the city. \"This clock has been loved for generations,\" the mayor said. Soon it will be moved to the new library so more people can enjoy it. A special case is being built to protect it. It will be displayed where children can learn its history. Such a gift should be treasured, and it always will be.","explanation_cn":"课文说 It was made entirely by hand。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"What will happen to the clock soon?","options":["It will be sold","It will be moved to the new library","It will be thrown away","It will be hidden"],"answer_index":1,"passage":"A beautiful old clock was given to our town by a famous artist long ago. It was made entirely by hand and is admired by everyone who sees it. For years it has been kept in the town hall''s main entrance. Every morning it is wound carefully by the caretaker. Recently it was repaired by an expert from the city. \"This clock has been loved for generations,\" the mayor said. Soon it will be moved to the new library so more people can enjoy it. A special case is being built to protect it. It will be displayed where children can learn its history. Such a gift should be treasured, and it always will be.","explanation_cn":"课文说 Soon it will be moved to the new library。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"Who repaired the clock recently?","options":["An expert from the city","The artist","A schoolchild","The mayor"],"answer_index":0,"audio":"A beautiful old clock was given to our town by a famous artist long ago. It was made entirely by hand and is admired by everyone who sees it. For years it has been kept in the town hall''s main entrance. Every morning it is wound carefully by the caretaker. Recently it was repaired by an expert from the city. \"This clock has been loved for generations,\" the mayor said. Soon it will be moved to the new library so more people can enjoy it. A special case is being built to protect it. It will be displayed where children can learn its history. Such a gift should be treasured, and it always will be.","explanation_cn":"课文说 Recently it was repaired by an expert from the city。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l93',10,NULL,'choice','{"stem":"Where has the clock been kept for years?","options":["In a museum","In a garden","In a school","In the town hall"],"answer_index":3,"audio":"A beautiful old clock was given to our town by a famous artist long ago. It was made entirely by hand and is admired by everyone who sees it. For years it has been kept in the town hall''s main entrance. Every morning it is wound carefully by the caretaker. Recently it was repaired by an expert from the city. \"This clock has been loved for generations,\" the mayor said. Soon it will be moved to the new library so more people can enjoy it. A special case is being built to protect it. It will be displayed where children can learn its history. Such a gift should be treasured, and it always will be.","explanation_cn":"课文说 For years it has been kept in the town hall''s main entrance。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l94',2,12,94,'The New Library','新图书馆','复习 KS21/45/69 被动语态各时态综合(方案B换情节包):一般现在/一般过去被动(is admired / was built)、现在完成被动(have been added)、将来被动(will be opened)、情态被动(can be taught / must be returned)、现在进行被动(is being built),以及被动句中用 by 引出动作的发出者','去年,我们镇建起了一座漂亮的新图书馆。它由一位著名的建筑师设计,人人都很喜爱。上万册图书已被添置到书架上。每天开馆前,阅览室都会被打扫干净。这里还免费开设各种课程,任何人都能学会使用电脑。上个月,一幅珍稀的古地图被捐赠过来,如今就陈列在大厅里。明年,二楼将开设一个儿童区。图书必须在三周内归还,否则会被收取一小笔罚款。至今已有一万多人参观过这座图书馆。全镇的人都爱它,它也将在未来很多年里被大家享用。','{"q":"Listen and answer — When was the new library built?","options":["Last year","Ten years ago","This month","Next year"],"answer_index":0}'::jsonb,'{"title":"复习 KS21/45/69 被动语态各时态","intro":"被动语态由 be + 过去分词构成,表示“被……”。本课在“新图书馆”的场景里复习各时态的被动:①一般现在/一般过去——is admired / was built;②现在完成——have been added(已被……);③将来——will be opened;④情态——can be taught / must be returned;⑤现在进行——is being built(正在被……)。被动句里若要说“由谁做的”,用 by 引出(was designed by a famous architect)。","table":{"headers":["时态(被动)","例子"],"rows":[["一般现在 / 一般过去","The rooms are cleaned daily. / It was built last year."],["现在完成","Thousands of books have been added."],["将来","A children''s section will be opened next year."],["情态","Anyone can be taught. / Books must be returned."],["现在进行 / by 短语","A room is being built. / It was designed by an architect."]]},"specialRules":[{"rule":"美语“二楼”说 second floor(英式 first floor);“公寓”说 apartment(英式 flat)。本课已按美语写。","mark":"second floor / apartment"},{"rule":"被动 = be 的相应时态 + 过去分词;情态被动是 can/must + be + 过去分词;现在进行被动是 is/are being + 过去分词;“由谁做”用 by 引出。","mark":"被动构成"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l94',1,NULL,'A beautiful new library was built in our town last year. It was designed by a famous architect and is admired by everyone.','去年,我们镇建起了一座漂亮的新图书馆。它由一位著名的建筑师设计,人人都很喜爱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l94',2,NULL,'Thousands of books have been added to its shelves. The reading rooms are cleaned every morning before opening.','上万册图书已被添置到书架上。每天开馆前,阅览室都会被打扫干净。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l94',3,NULL,'Free classes are offered there, and anyone can be taught to use the computers. Last month, a rare old map was donated and is now displayed in the hall.','这里还免费开设各种课程,任何人都能学会使用电脑。上个月,一幅珍稀的古地图被捐赠过来,如今就陈列在大厅里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l94',4,NULL,'Next year, a children''s section will be opened on the second floor. Books must be returned within three weeks, or a small fine is charged.','明年,二楼将开设一个儿童区。图书必须在三周内归还,否则会被收取一小笔罚款。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l94',5,NULL,'The library has been visited by more than ten thousand people already. It is loved by the whole town, and it will be enjoyed for many years to come.','至今已有一万多人参观过这座图书馆。全镇的人都爱它,它也将在未来很多年里被大家享用。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
