INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp1','choice','{"stem":"\"A beautiful new library ___ in our town last year.\"(一般过去被动:被建造)","options":["is built","built","has built","was built"],"answer_index":3,"stem_cn":"去年我们镇建起了一座漂亮的新图书馆。","explanation_cn":"过去“被建造”,用一般过去被动 was + 过去分词。✓ A new library was built last year. ✗ built:主动;✗ is built:一般现在被动,与 last year 不符;✗ has built:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp1','choice','{"stem":"\"It ___ by everyone in town.\"(一般现在被动:被喜爱)","options":["admires","was admired","is admired","is admiring"],"answer_index":2,"stem_cn":"镇上人人都喜爱它。","explanation_cn":"经常性地“被喜爱”,用一般现在被动 is + 过去分词。✓ It is admired by everyone. ✗ admires:主动;✗ was admired:一般过去;✗ is admiring:进行主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp1','choice','{"stem":"\"The reading rooms ___ every morning before opening.\"(一般现在被动:被打扫)","options":["clean","are cleaned","were cleaned","are cleaning"],"answer_index":1,"stem_cn":"每天开馆前,阅览室都会被打扫。","explanation_cn":"每天“被打扫”,用一般现在被动 are + 过去分词。✓ The reading rooms are cleaned every morning. ✗ clean:主动;✗ are cleaning:进行主动;✗ were cleaned:一般过去,与 every morning 不符。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp2','choice','{"stem":"\"Thousands of books ___ to its shelves.\"(现在完成被动:已被添置)","options":["have been added","were adding","are added","have added"],"answer_index":0,"stem_cn":"上万册图书已被添置到书架上。","explanation_cn":"“已被添置”,用现在完成被动 have been + 过去分词。✓ Thousands of books have been added. ✗ have added:现在完成主动;✗ are added:一般现在被动;✗ were adding:过去进行主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp2','choice','{"stem":"\"The library ___ by more than ten thousand people already.\"(现在完成被动:已被参观)","options":["was visiting","is visited","has visited","has been visited"],"answer_index":3,"stem_cn":"至今已有一万多人参观过这座图书馆。","explanation_cn":"“已被参观”,用现在完成被动。✓ The library has been visited by many people already. ✗ has visited:现在完成主动;✗ is visited:一般现在被动;✗ was visiting:过去进行主动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp2','choice','{"stem":"\"Many new computers ___ this year.\"(现在完成被动:已被安装)","options":["have installed","have been installed","are installing","installed"],"answer_index":1,"stem_cn":"今年已安装了许多新电脑。","explanation_cn":"“已被安装”,用现在完成被动。✓ Many new computers have been installed this year. ✗ have installed:现在完成主动;✗ are installing:进行主动;✗ installed:一般过去。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp3','choice','{"stem":"\"Next year, a children''s section ___ on the second floor.\"(将来被动:将被开设)","options":["will be opened","has opened","will open","is opened"],"answer_index":0,"stem_cn":"明年二楼将开设一个儿童区。","explanation_cn":"将来“被开设”,用将来被动 will be + 过去分词。✓ A children''s section will be opened next year. ✗ will open:将来主动;✗ is opened:一般现在被动;✗ has opened:现在完成主动。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp3','choice','{"stem":"\"It ___ by the whole town for years to come.\"(将来被动:将被享用)","options":["enjoyed","will be enjoyed","is enjoyed","will enjoy"],"answer_index":1,"stem_cn":"它将在未来很多年里被全镇享用。","explanation_cn":"将来“被享用”,用将来被动。✓ It will be enjoyed for years to come. ✗ will enjoy:将来主动;✗ is enjoyed:一般现在被动;✗ enjoyed:一般过去。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp3','choice','{"stem":"\"A new sign ___ above the door next week.\"(将来被动:将被挂)","options":["put","will put","will be put","is putting"],"answer_index":2,"stem_cn":"下周门上方将挂一块新招牌。","explanation_cn":"将来“被挂上”,用将来被动。✓ A new sign will be put above the door next week. ✗ will put:将来主动;✗ is putting:进行主动;✗ put:主动。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp4','choice','{"stem":"\"Anyone ___ to use the computers there.\"(情态被动:能被教)","options":["teaches","is teaching","can teach","can be taught"],"answer_index":3,"stem_cn":"任何人都能在那里被教会用电脑。","explanation_cn":"情态“能被教”,用 can + be + 过去分词。✓ Anyone can be taught to use the computers. ✗ can teach:主动;✗ teaches:一般现在主动;✗ is teaching:进行主动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp4','choice','{"stem":"\"Books ___ within three weeks.\"(情态被动:必须被归还)","options":["returns","must return","must be returned","is returning"],"answer_index":2,"stem_cn":"图书必须在三周内归还。","explanation_cn":"情态“必须被归还”,用 must + be + 过去分词。✓ Books must be returned within three weeks. ✗ must return:主动;✗ returns:一般现在主动;✗ is returning:进行主动。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp4','choice','{"stem":"\"Food ___ into the reading rooms.\"(情态被动的否定:不得被带入)","options":["doesn''t bring","must not bring","isn''t bringing","must not be brought"],"answer_index":3,"stem_cn":"食物不得被带入阅览室。","explanation_cn":"情态被动的否定“不得被带入”,用 must not + be + 过去分词。✓ Food must not be brought into the reading rooms. ✗ must not bring:主动;✗ doesn''t bring:一般现在主动;✗ isn''t bringing:进行主动。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp5','choice','{"stem":"\"Right now, a new reading room ___ upstairs.\"(现在进行被动:正在被建造)","options":["is being built","has built","builds","is building"],"answer_index":0,"stem_cn":"此刻,楼上正在建一间新阅览室。","explanation_cn":"此刻“正在被建造”,用现在进行被动 is being + 过去分词。✓ A new reading room is being built upstairs. ✗ is building:进行主动;✗ builds:一般现在主动;✗ has built:现在完成主动。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp5','choice','{"stem":"\"The shelves ___ by workers at the moment.\"(现在进行被动:正在被整理)","options":["are arranging","are being arranged","arrange","arranged"],"answer_index":1,"stem_cn":"此刻工人们正在整理书架。","explanation_cn":"此刻“正在被整理”,用现在进行被动 are being + 过去分词。✓ The shelves are being arranged by workers. ✗ are arranging:进行主动;✗ arrange:一般现在主动;✗ arranged:一般过去。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp5','choice','{"stem":"\"The library was designed ___ a famous architect.\"(被动句里引出“由谁设计”)","options":["with","for","by","of"],"answer_index":2,"stem_cn":"这座图书馆由一位著名建筑师设计。","explanation_cn":"被动句里引出“由谁做”,用 by。✓ The library was designed by a famous architect. ✗ with:表工具/材料;✗ for:为了;✗ of:属于。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp6','choice','{"stem":"\"The books are kept on tall ___.\"(书架用哪个词)","options":["rivers","shelves","clouds","roads"],"answer_index":1,"stem_cn":"书都放在高高的书架上。","explanation_cn":"放书的“书架、架子”是 shelf(复数 shelves)。✓ kept on tall shelves. ✗ rivers:河;✗ clouds:云;✗ roads:路。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp6','choice','{"stem":"\"A rare old map was ___ to the library.\"(捐赠用哪个词)","options":["donated","painted","lost","eaten"],"answer_index":0,"stem_cn":"一幅珍稀的古地图被捐给了图书馆。","explanation_cn":"“捐赠”是 donate(过去分词 donated)。✓ A rare old map was donated. ✗ eaten:被吃;✗ painted:被画;✗ lost:丢失。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',5,'am2_l94_gp6','choice','{"stem":"\"The library was designed by a famous ___.\"(建筑师用哪个词)","options":["driver","architect","singer","cook"],"answer_index":1,"stem_cn":"这座图书馆由一位著名建筑师设计。","explanation_cn":"设计房屋、建筑的“建筑师”是 architect。✓ designed by a famous architect. ✗ cook:厨师;✗ singer:歌手;✗ driver:司机。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',6,NULL,'choice','{"stem":"美语里\"二楼\"说:","options":["level-two","first floor","upper-one","second floor"],"answer_index":3,"explanation_cn":"美语“二楼”说 second floor;英式说 first floor。✓ The children''s section is on the second floor. 儿童区在二楼。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',6,NULL,'choice','{"stem":"美语里\"公寓\"说:","options":["room-set","apartment","house-unit","flat"],"answer_index":1,"explanation_cn":"美语“公寓”说 apartment;英式说 flat。✓ She lives in an apartment near the library. 她住在图书馆附近的一套公寓里。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',6,NULL,'choice','{"stem":"library 的意思是:","options":["实验室","体育馆","图书馆","餐厅"],"answer_index":2,"explanation_cn":"library = 图书馆。✓ a beautiful new library 一座漂亮的新图书馆。\n顺带记:实验室 = lab;体育馆 = gym;餐厅 = dining hall."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',6,NULL,'choice','{"stem":"donate 的意思是:","options":["出售","捐赠","打碎","借入"],"answer_index":1,"explanation_cn":"donate = 捐赠。✓ a rare old map was donated 一幅古地图被捐赠。\n顺带记:出售 = sell;借入 = borrow;打碎 = break."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',6,NULL,'choice','{"stem":"offer 的意思是:","options":["提供","隐藏","损坏","拒绝"],"answer_index":0,"explanation_cn":"offer = 提供。✓ Free classes are offered 免费开设课程。\n顺带记:拒绝 = refuse;隐藏 = hide;损坏 = damage."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',6,NULL,'choice','{"stem":"return 的意思是:","options":["打碎","丢失","购买","归还,返回"],"answer_index":3,"explanation_cn":"return = 归还、返回。✓ Books must be returned 图书必须归还。\n顺带记:购买 = buy;丢失 = lose;打碎 = break."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',7,NULL,'cloze','{"stem":"第 1 空","context":"A beautiful new library ___1___ last year. Thousands of books ___2___ to its shelves. Next year, a children''s section ___3___ upstairs. Books ___4___ within three weeks.","blank_no":1,"options":["was built","built","is built","has built"],"answer_index":0,"explanation_cn":"过去“被建造”,用一般过去被动。✓ A beautiful new library was built last year.\n✗ built:主动;✗ is built:一般现在;✗ has built:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',7,NULL,'cloze','{"stem":"第 2 空","context":"A beautiful new library ___1___ last year. Thousands of books ___2___ to its shelves. Next year, a children''s section ___3___ upstairs. Books ___4___ within three weeks.","blank_no":2,"options":["have been added","have added","are adding","added"],"answer_index":0,"explanation_cn":"“已被添置”,用现在完成被动。✓ Thousands of books have been added to its shelves.\n✗ have added:现在完成主动;✗ are adding:进行主动;✗ added:一般过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',7,NULL,'cloze','{"stem":"第 3 空","context":"A beautiful new library ___1___ last year. Thousands of books ___2___ to its shelves. Next year, a children''s section ___3___ upstairs. Books ___4___ within three weeks.","blank_no":3,"options":["will be opened","will open","is opened","opened"],"answer_index":0,"explanation_cn":"将来“被开设”,用将来被动。✓ A children''s section will be opened upstairs.\n✗ will open:将来主动;✗ is opened:一般现在;✗ opened:一般过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',7,NULL,'cloze','{"stem":"第 4 空","context":"A beautiful new library ___1___ last year. Thousands of books ___2___ to its shelves. Next year, a children''s section ___3___ upstairs. Books ___4___ within three weeks.","blank_no":4,"options":["must be returned","must return","returns","returned"],"answer_index":0,"explanation_cn":"情态“必须被归还”,用 must + be + 过去分词。✓ Books must be returned within three weeks.\n✗ must return:主动;✗ must be return:缺过去分词;✗ returned:缺 be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',8,NULL,'choice','{"stem":"When was the new library built?","options":["Ten years ago","This month","Next year","Last year"],"answer_index":3,"explanation_cn":"课文说 A beautiful new library was built in our town last year。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',8,NULL,'choice','{"stem":"What was donated to the library last month?","options":["A painting","A new computer","A rare old map","A piano"],"answer_index":2,"explanation_cn":"课文说 Last month, a rare old map was donated。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',8,NULL,'choice','{"stem":"How long can books be kept before they must be returned?","options":["Three weeks","Three days","Three months","One year"],"answer_index":0,"explanation_cn":"课文说 Books must be returned within three weeks。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',9,NULL,'choice','{"stem":"你想说\"去年我们镇建了一座漂亮的新图书馆\"(一般过去被动):","options":["A beautiful new library is built in our town last year.","A beautiful new library was built in our town last year.","A beautiful new library built in our town last year.","A beautiful new library has built in our town last year."],"answer_index":1,"explanation_cn":"过去“被建造”,用一般过去被动 was + 过去分词。✓ A beautiful new library was built in our town last year. 场合:说某物在过去被建成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',9,NULL,'choice','{"stem":"你想说\"成千上万本书已经被添到书架上\"(现在完成被动):","options":["Thousands of books were adding to its shelves.","Thousands of books have added to its shelves.","Thousands of books are added to its shelves.","Thousands of books have been added to its shelves."],"answer_index":3,"explanation_cn":"“已被添置”,用现在完成被动 have been + 过去分词。✓ Thousands of books have been added to its shelves. 场合:说某物已被添加到某处。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',9,NULL,'choice','{"stem":"你想说\"书必须在三周内归还\"(情态被动):","options":["Books must be returned within three weeks.","Books must return within three weeks.","Books must returned within three weeks.","Books must be return within three weeks."],"answer_index":0,"explanation_cn":"情态“必须被归还”,用 must + be + 过去分词。✓ Books must be returned within three weeks. 场合:说某物必须在规定期限内被归还。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"library 的意思是:","options":["体育馆","图书馆","餐厅","实验室"],"answer_index":1,"explanation_cn":"library = 图书馆。✓ a beautiful new library 一座漂亮的新图书馆。\n顺带记:实验室 = lab;体育馆 = gym;餐厅 = dining hall."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"architect 的意思是:","options":["建筑师","司机","歌手","厨师"],"answer_index":0,"explanation_cn":"architect = 建筑师。✓ designed by a famous architect 由著名建筑师设计。\n顺带记:厨师 = cook;歌手 = singer;司机 = driver."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"\"The reading rooms ___ every morning before opening.\"(一般现在被动)","options":["were cleaned","clean","are cleaned","are cleaning"],"answer_index":2,"stem_cn":"每天开馆前,阅览室都会被打扫。","explanation_cn":"每天“被打扫”,用一般现在被动。✓ The reading rooms are cleaned every morning.\n✗ clean:主动;✗ are cleaning:进行主动;✗ were cleaned:一般过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"\"Next year, a children''s section ___ on the second floor.\"(将来被动)","options":["has opened","will be opened","is opened","will open"],"answer_index":1,"stem_cn":"明年二楼将开设一个儿童区。","explanation_cn":"将来“被开设”,用将来被动。✓ A children''s section will be opened on the second floor.\n✗ will open:将来主动;✗ is opened:一般现在;✗ has opened:现在完成主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"\"for years to come\" 的意思是:","options":["在未来很多年里","一年之内","为了未来","多年以前"],"answer_index":0,"explanation_cn":"for years to come = 在未来很多年里。✓ It will be enjoyed for years to come。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"\"on the second floor\" 的意思是:","options":["在楼下","在地面上","在二楼","在第二秒"],"answer_index":2,"explanation_cn":"on the second floor = 在二楼(美语 second floor = 二楼)。✓ a children''s section on the second floor。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"Who designed the new library?","options":["A famous architect","The mayor","A local artist","A schoolteacher"],"answer_index":0,"passage":"A beautiful new library was built in our town last year. It was designed by a famous architect and is admired by everyone. Thousands of books have been added to its shelves. The reading rooms are cleaned every morning before opening. Free classes are offered there, and anyone can be taught to use the computers. Last month, a rare old map was donated and is now displayed in the hall. Next year, a children''s section will be opened on the second floor. Books must be returned within three weeks, or a small fine is charged. The library has been visited by more than ten thousand people already. It is loved by the whole town, and it will be enjoyed for many years to come.","explanation_cn":"课文说 It was designed by a famous architect。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"What must readers do within three weeks?","options":["Move house","Return their books","Pay for a card","Buy new books"],"answer_index":1,"passage":"A beautiful new library was built in our town last year. It was designed by a famous architect and is admired by everyone. Thousands of books have been added to its shelves. The reading rooms are cleaned every morning before opening. Free classes are offered there, and anyone can be taught to use the computers. Last month, a rare old map was donated and is now displayed in the hall. Next year, a children''s section will be opened on the second floor. Books must be returned within three weeks, or a small fine is charged. The library has been visited by more than ten thousand people already. It is loved by the whole town, and it will be enjoyed for many years to come.","explanation_cn":"课文说 Books must be returned within three weeks——读者要在三周内还书。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"When was the library built?","options":["Last year","This week","Ten years ago","Next year"],"answer_index":0,"audio":"A beautiful new library was built in our town last year. It was designed by a famous architect and is admired by everyone. Thousands of books have been added to its shelves. The reading rooms are cleaned every morning before opening. Free classes are offered there, and anyone can be taught to use the computers. Last month, a rare old map was donated and is now displayed in the hall. Next year, a children''s section will be opened on the second floor. Books must be returned within three weeks, or a small fine is charged. The library has been visited by more than ten thousand people already. It is loved by the whole town, and it will be enjoyed for many years to come.","explanation_cn":"课文说 A beautiful new library was built in our town last year。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l94',10,NULL,'choice','{"stem":"What was donated last month?","options":["A statue","A new piano","A painting","A rare old map"],"answer_index":3,"audio":"A beautiful new library was built in our town last year. It was designed by a famous architect and is admired by everyone. Thousands of books have been added to its shelves. The reading rooms are cleaned every morning before opening. Free classes are offered there, and anyone can be taught to use the computers. Last month, a rare old map was donated and is now displayed in the hall. Next year, a children''s section will be opened on the second floor. Books must be returned within three weeks, or a small fine is charged. The library has been visited by more than ten thousand people already. It is loved by the whole town, and it will be enjoyed for many years to come.","explanation_cn":"课文说 Last month, a rare old map was donated。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l95',2,12,95,'A Very Special Day','非常特别的一天','复习全册动词形式综合(收官包·方案B换情节):各时态(一般现在/现在完成进行/过去/过去完成/过去进行/一般将来)、被动(一般现在被动/现在进行被动/过去完成被动/将来被动)、条件句、情态等在一个故事里的综合运用辨析','每年秋天,我们镇都会办一场人人翘首以盼的丰收节。今年,我已经帮着筹备了两个月。广场附近搭起了一个个摊位,一串串彩灯早已挂满了广场上空。“要是下雨,整场活动就挪到室内。”“你一定要尝尝苹果派,”朋友说,“现在正端上来呢。”孩子们笑作一团,台上的乐手们奏着欢快的曲子。到了傍晚,已经来了好几百人,还有更多人正陆续赶来。“我从没见过镇子这么热闹,”奶奶说。大家都说,明年的丰收节会办得更大。这真是让人久久难忘的一天。','{"q":"Listen and answer — How often does the town hold the harvest festival?","options":["Every fall","Every week","Once every ten years","Only this year"],"answer_index":0}'::jsonb,'{"title":"复习全册动词形式综合","intro":"本课把学过的各种动词形式放进一个丰收节的故事里综合辨析:①一般现在——每年惯例(our town holds a festival);②现在完成进行——一直做到现在(I have been helping for two months);③过去/过去完成(被动)——搭好的摊位、早已挂好的灯(booths were set up / lights had been hung);④过去进行——当时正在做(children were laughing);⑤条件 + 将来被动——(If it rains, the event will be moved indoors);⑥现在进行被动——此刻正被做(the pie is being served);⑦现在完成——影响到现在(I have never seen it so alive);⑧一般将来 / 将来被动——(next year''s festival will be bigger / it will be remembered)。看时间标志和语义选形式。","table":{"headers":["形式","例子"],"rows":[["一般现在 / 现在完成进行","Our town holds a festival. / I have been helping for two months."],["过去 / 过去完成被动","Booths were set up. / Lights had been hung."],["过去进行","Children were laughing while musicians were playing."],["条件 + 将来被动","If it rains, the event will be moved indoors."],["现在进行被动 / 将来被动","The pie is being served. / It will be remembered."]]},"specialRules":[{"rule":"美语“秋天”说 fall(英式 autumn);“糖果”说 candy(英式 sweets)。本课已按美语写。","mark":"fall / candy"},{"rule":"综合题看时间标志和语义选形式:每年惯例用一般现在,当时正在做用过去进行,条件从句用一般现在表将来,此刻正被做用现在进行被动。","mark":"综合辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l95',1,NULL,'Every fall, our town holds a harvest festival that everyone looks forward to. This year, I have been helping to plan it for two months.','每年秋天,我们镇都会办一场人人翘首以盼的丰收节。今年,我已经帮着筹备了两个月。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l95',2,NULL,'Booths were set up near the square, and lights had been hung across it. "If it rains, the whole event will be moved indoors."','广场附近搭起了一个个摊位,一串串彩灯早已挂满了广场上空。“要是下雨,整场活动就挪到室内。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l95',3,NULL,'"You must try the apple pie," my friend said. "It is being served now." Children were laughing while musicians were playing on the stage.','“你一定要尝尝苹果派,”朋友说,“现在正端上来呢。”孩子们笑作一团,台上的乐手们奏着欢快的曲子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l95',4,NULL,'By evening, hundreds of people had come, and more were arriving. "I have never seen the town so alive," Grandma said.','到了傍晚,已经来了好几百人,还有更多人正陆续赶来。“我从没见过镇子这么热闹,”奶奶说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l95',5,NULL,'Next year''s festival will be even bigger, everyone agrees. It was a day that will be remembered for a long time.','大家都说,明年的丰收节会办得更大。这真是让人久久难忘的一天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
