INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l95','look forward to','',NULL,'/lʊk ˈfɔːrwərd tu/','Everyone looks forward to the harvest festival.','人人都期待着丰收节。','I look forward to seeing you there.','我期待在那儿见到你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l95','set up','',NULL,'/set ʌp/','Booths were set up near the square.','广场附近搭起了摊位。','They set up a stage for the show.','他们为演出搭了个舞台。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l95','harvest festival','',NULL,'/ˈhɑːrvɪst ˈfestɪvl/','Our town holds a harvest festival every fall.','我们镇每年秋天办丰收节。','The harvest festival lasts a whole weekend.','丰收节持续整个周末。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l95','for a long time','',NULL,'/fɔːr ə lɔːŋ taɪm/','It will be remembered for a long time.','它将被人们久久铭记。','We waited for a long time.','我们等了很久。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp1','choice','{"stem":"\"Every fall, our town ___ a harvest festival.\"(每年惯例:一般现在)","options":["held","is holding","holds","has held"],"answer_index":2,"stem_cn":"每年秋天,我们镇都举办丰收节。","explanation_cn":"每年惯例,用一般现在时。✓ Every fall, our town holds a harvest festival. ✗ is holding:进行,表此刻;✗ held:一般过去;✗ has held:现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp1','choice','{"stem":"\"This year, I ___ to plan it for two months.\"(一直帮忙到现在:现在完成进行)","options":["helped","am helping","help","have been helping"],"answer_index":3,"stem_cn":"今年,我已经帮着筹备两个月了。","explanation_cn":"从过去一直帮忙到现在,用现在完成进行时 have been + doing。✓ I have been helping to plan it for two months. ✗ helped:一般过去;✗ help:一般现在;✗ am helping:现在进行,不强调“持续两个月”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp1','choice','{"stem":"\"''I ___ the town so alive,'' Grandma said.\"(从未见过:现在完成)","options":["had never seen","have never seen","am never seeing","never saw"],"answer_index":1,"stem_cn":"“我从没见过镇子这么热闹,”奶奶说。","explanation_cn":"“从未见过”,经验类,用现在完成时。✓ I have never seen the town so alive. ✗ never saw:缺 have;✗ am never seeing:进行;✗ had never seen:过去完成,与“说话此刻”不符。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp2','choice','{"stem":"\"Booths ___ near the square for the festival.\"(过去被动:被搭起)","options":["are set up","set up","were set up","have set up"],"answer_index":2,"stem_cn":"广场附近为丰收节搭起了摊位。","explanation_cn":"过去“被搭起”,用一般过去被动 were + 过去分词。✓ Booths were set up near the square. ✗ set up:主动;✗ are set up:一般现在被动;✗ have set up:现在完成主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp2','choice','{"stem":"\"Lights ___ across the square before the crowd arrived.\"(过去完成被动:此前已被挂上)","options":["have hung","hung","are hung","had been hung"],"answer_index":3,"stem_cn":"人群到之前,彩灯早已挂满了广场上空。","explanation_cn":"“人群到之前早已被挂上”,用过去完成被动 had been + 过去分词。✓ Lights had been hung across the square. ✗ hung:一般过去主动;✗ are hung:一般现在被动;✗ have hung:现在完成主动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp2','choice','{"stem":"\"Children ___ while musicians were playing on the stage.\"(当时正在:过去进行)","options":["laughed","were laughing","have laughed","laugh"],"answer_index":1,"stem_cn":"台上乐手演奏时,孩子们笑作一团。","explanation_cn":"过去某时“正在笑”,用过去进行时 were + doing。✓ Children were laughing while musicians were playing. ✗ laughed:一般过去;✗ laugh:一般现在;✗ have laughed:现在完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp3','choice','{"stem":"\"If it ___, the whole event will be moved indoors.\"(条件从句用一般现在表将来)","options":["rains","is raining","rained","will rain"],"answer_index":0,"stem_cn":"要是下雨,整场活动就挪到室内。","explanation_cn":"if 条件从句里用一般现在时表示将来。✓ If it rains, the whole event will be moved indoors. ✗ will rain:从句里不用 will;✗ is raining:进行;✗ rained:一般过去。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp3','choice','{"stem":"\"Next year''s festival ___ even bigger.\"(一般将来)","options":["is","has been","will be","was"],"answer_index":2,"stem_cn":"明年的丰收节会办得更大。","explanation_cn":"对将来的判断,用一般将来时。✓ Next year''s festival will be even bigger. ✗ is:一般现在;✗ was:过去;✗ has been:现在完成。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp3','choice','{"stem":"\"If it rains, the event ___ indoors.\"(条件主句:将来被动)","options":["will be moved","is moved","moved","will move"],"answer_index":0,"stem_cn":"要是下雨,活动就会被挪到室内。","explanation_cn":"将来“被挪到室内”,用将来被动 will be + 过去分词。✓ If it rains, the event will be moved indoors. ✗ will move:将来主动;✗ is moved:一般现在被动;✗ moved:一般过去。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp4','choice','{"stem":"\"''You must try the apple pie. It ___ now,'' my friend said.\"(现在进行被动:正在被供应)","options":["is serving","served","is being served","serves"],"answer_index":2,"stem_cn":"“你一定要尝尝苹果派,现在正端上来呢。”","explanation_cn":"此刻“正在被供应”,用现在进行被动 is being + 过去分词。✓ The apple pie is being served now. ✗ is serving:进行主动;✗ serves:一般现在主动;✗ served:一般过去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp4','choice','{"stem":"\"It was a day that ___ for a long time.\"(将来被动:将被铭记)","options":["is remembering","will remember","remembered","will be remembered"],"answer_index":3,"stem_cn":"这真是让人久久难忘的一天。","explanation_cn":"将来“被铭记”,用将来被动 will be + 过去分词。✓ a day that will be remembered for a long time. ✗ will remember:将来主动;✗ is remembering:进行主动;✗ remembered:一般过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp4','choice','{"stem":"\"The square ___ with colorful flags every year.\"(一般现在被动:被装饰)","options":["decorates","is decorated","decorate","is decorating"],"answer_index":1,"stem_cn":"广场每年都用彩旗装饰。","explanation_cn":"每年“被装饰”,用一般现在被动 is + 过去分词。✓ The square is decorated with flags every year. ✗ decorates:主动;✗ is decorating:进行主动;✗ decorate:主语单数不搭。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp5','choice','{"stem":"\"''You ___ try the apple pie,'' my friend said.\"(强烈建议:一定要)","options":["can","may","would","must"],"answer_index":3,"stem_cn":"“你一定要尝尝苹果派,”朋友说。","explanation_cn":"强烈建议“一定要”,用 must + 动词原形。✓ You must try the apple pie. ✗ can:能够;✗ may:也许/可以;✗ would:意愿。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp5','choice','{"stem":"\"By evening, hundreds of people ___, and more were arriving.\"(此前已经来了:过去完成)","options":["come","are coming","had come","will come"],"answer_index":2,"stem_cn":"到傍晚,已经来了好几百人,还有更多人正赶来。","explanation_cn":"“到傍晚之前已经来了”,用过去完成时 had + 过去分词。✓ By evening, hundreds of people had come. ✗ come:缺 had;✗ are coming:现在进行;✗ will come:将来。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp5','choice','{"stem":"\"By evening, hundreds had come, and more ___.\"(当时正陆续赶来:过去进行)","options":["arrived","have arrived","arrive","were arriving"],"answer_index":3,"stem_cn":"到傍晚,已经来了好几百人,还有更多人正陆续赶来。","explanation_cn":"过去那时“正陆续赶来”,用过去进行时。✓ …and more were arriving. ✗ arrived:一般过去,不表“正在陆续”;✗ arrive:一般现在;✗ have arrived:现在完成。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp6','choice','{"stem":"\"Every fall the town holds a harvest ___.\"(节日、庆典用哪个词)","options":["festival","meeting","hospital","mistake"],"answer_index":0,"stem_cn":"每年秋天镇上都办丰收节。","explanation_cn":"“节日、庆典”是 festival。✓ a harvest festival. ✗ hospital:医院;✗ mistake:错误;✗ meeting:会议。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp6','choice','{"stem":"\"The ___ played happy music on the stage.\"(乐手、音乐家用哪个词)","options":["farmers","musicians","doctors","drivers"],"answer_index":1,"stem_cn":"乐手们在台上演奏欢快的音乐。","explanation_cn":"演奏音乐的“乐手、音乐家”是 musician(复数 musicians)。✓ The musicians played happy music. ✗ farmers:农民;✗ doctors:医生;✗ drivers:司机。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',5,'am2_l95_gp6','choice','{"stem":"\"''I have never seen the town so ___,'' Grandma said.\"(热闹的、有生气的用哪个词)","options":["empty","asleep","quiet","alive"],"answer_index":3,"stem_cn":"“我从没见过镇子这么热闹,”奶奶说。","explanation_cn":"“有生气的、热闹的”是 alive。✓ the town so alive. ✗ empty:空的;✗ quiet:安静的;✗ asleep:睡着的。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',6,NULL,'choice','{"stem":"美语里\"秋天\"说:","options":["cool-fall","harvest-time","autumn","fall"],"answer_index":3,"explanation_cn":"美语“秋天”说 fall;英式说 autumn。✓ The festival is held every fall. 丰收节每年秋天举办。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',6,NULL,'choice','{"stem":"美语里\"糖果\"说:","options":["sweeties","candy","sugar-drops","sweets"],"answer_index":1,"explanation_cn":"美语“糖果”说 candy;英式说 sweets。✓ The children bought candy at the booth. 孩子们在摊位上买了糖果。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',6,NULL,'choice','{"stem":"harvest 的意思是:","options":["干旱","洪水","播种","收获,丰收"],"answer_index":3,"explanation_cn":"harvest = 收获、丰收。✓ a harvest festival 丰收节。\n顺带记:播种 = sow;干旱 = drought;洪水 = flood."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',6,NULL,'choice','{"stem":"booth 的意思是:","options":["桥梁","摊位,小亭","隧道","屋顶"],"answer_index":1,"explanation_cn":"booth = 摊位、小亭。✓ Booths were set up 搭起了摊位。\n顺带记:桥梁 = bridge;隧道 = tunnel;屋顶 = roof."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',6,NULL,'choice','{"stem":"alive 的意思是:","options":["空荡荡的","睡着的","安静的","有生气的,热闹的"],"answer_index":3,"explanation_cn":"alive = 有生气的、热闹的;也指“活着的”。✓ the town so alive 镇子这么热闹。\n顺带记:空荡荡的 = empty;安静的 = quiet;睡着的 = asleep."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',6,NULL,'choice','{"stem":"remember 的意思是:","options":["记得,铭记","隐藏","打碎","忘记"],"answer_index":0,"explanation_cn":"remember = 记得、铭记。✓ will be remembered 将被铭记。\n顺带记:忘记 = forget;隐藏 = hide;打碎 = break."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',7,NULL,'cloze','{"stem":"第 1 空","context":"Every fall, our town ___1___ a harvest festival. This year, I ___2___ to plan it for two months. If it rains, the event ___3___ indoors. \"You must try the pie — it ___4___ now.\"","blank_no":1,"options":["holds","is holding","held","has held"],"answer_index":0,"explanation_cn":"每年惯例,用一般现在时。✓ Every fall, our town holds a harvest festival.\n✗ is holding:进行;✗ held:一般过去;✗ has held:现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',7,NULL,'cloze','{"stem":"第 2 空","context":"Every fall, our town ___1___ a harvest festival. This year, I ___2___ to plan it for two months. If it rains, the event ___3___ indoors. \"You must try the pie — it ___4___ now.\"","blank_no":2,"options":["have been helping","helped","help","am helping"],"answer_index":0,"explanation_cn":"一直帮忙到现在,用现在完成进行时。✓ I have been helping to plan it for two months.\n✗ helped:一般过去;✗ help:一般现在;✗ am helping:现在进行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',7,NULL,'cloze','{"stem":"第 3 空","context":"Every fall, our town ___1___ a harvest festival. This year, I ___2___ to plan it for two months. If it rains, the event ___3___ indoors. \"You must try the pie — it ___4___ now.\"","blank_no":3,"options":["will be moved","will move","is moved","moved"],"answer_index":0,"explanation_cn":"将来“被挪到室内”,用将来被动。✓ If it rains, the event will be moved indoors.\n✗ will move:将来主动;✗ is moved:一般现在被动;✗ moved:一般过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',7,NULL,'cloze','{"stem":"第 4 空","context":"Every fall, our town ___1___ a harvest festival. This year, I ___2___ to plan it for two months. If it rains, the event ___3___ indoors. \"You must try the pie — it ___4___ now.\"","blank_no":4,"options":["is being served","is serving","serves","served"],"answer_index":0,"explanation_cn":"此刻“正在被供应”,用现在进行被动。✓ The pie is being served now.\n✗ is serving:进行主动;✗ serves:一般现在主动;✗ served:一般过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',8,NULL,'choice','{"stem":"How often does the town hold the harvest festival?","options":["Every week","Only this year","Once a decade","Every fall"],"answer_index":3,"explanation_cn":"课文说 Every fall, our town holds a harvest festival。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',8,NULL,'choice','{"stem":"What will happen if it rains?","options":["The event will be moved indoors","Nothing will change","The event will be canceled","It will start earlier"],"answer_index":0,"explanation_cn":"课文说 If it rains, the whole event will be moved indoors。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',8,NULL,'choice','{"stem":"What did Grandma say about the town?","options":["It was smaller than before","She had never seen it so alive","It looked empty","It was too quiet"],"answer_index":1,"explanation_cn":"课文说 \"I have never seen the town so alive,\" Grandma said。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',9,NULL,'choice','{"stem":"你想说\"今年我已经帮着筹备两个月了\"(现在完成进行):","options":["This year, I am helping to plan it for two months.","This year, I have been helping to plan it for two months.","This year, I help to plan it for two months.","This year, I helped to plan it for two months."],"answer_index":1,"explanation_cn":"从过去一直做到现在,用现在完成进行时 have been + doing。✓ This year, I have been helping to plan it for two months. 场合:强调某动作持续到现在。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',9,NULL,'choice','{"stem":"你想说\"如果下雨,整个活动就会挪到室内\"(条件从句用现在时 + 主句将来被动):","options":["If it will rain, the whole event will move indoors.","If it rains, the whole event will move indoors.","If it rains, the whole event will be moved indoors.","If it rained, the whole event will be moved indoors."],"answer_index":2,"explanation_cn":"条件从句用一般现在时表将来,主句用将来被动。✓ If it rains, the whole event will be moved indoors. 场合:说“如果……,某事就会被……”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',9,NULL,'choice','{"stem":"你想说\"苹果派现在正在供应\"(现在进行被动):","options":["The apple pie has served now.","The apple pie serves now.","The apple pie is serving now.","The apple pie is being served now."],"answer_index":3,"explanation_cn":"此刻“正在被供应”,用现在进行被动 is being + 过去分词。✓ The apple pie is being served now. 场合:说某物此刻正被端上、供应。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"festival 的意思是:","options":["节日,庆典","错误","医院","会议"],"answer_index":0,"explanation_cn":"festival = 节日、庆典。✓ a harvest festival 丰收节。\n顺带记:医院 = hospital;错误 = mistake;会议 = meeting."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"alive 的意思是:","options":["睡着的","有生气的,热闹的","空荡荡的","安静的"],"answer_index":1,"explanation_cn":"alive = 有生气的、热闹的。✓ the town so alive 镇子这么热闹。\n顺带记:空荡荡的 = empty;安静的 = quiet;睡着的 = asleep."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"\"Every fall, our town ___ a harvest festival.\"(每年惯例:一般现在)","options":["holds","is holding","held","has held"],"answer_index":0,"stem_cn":"每年秋天镇上都办丰收节。","explanation_cn":"每年惯例,用一般现在时。✓ Every fall, our town holds a harvest festival.\n✗ is holding:进行;✗ held:一般过去;✗ has held:现在完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"\"If it rains, the event ___ indoors.\"(条件主句:将来被动)","options":["will move","moved","is moved","will be moved"],"answer_index":3,"stem_cn":"要是下雨,活动就会被挪到室内。","explanation_cn":"将来“被挪到室内”,用将来被动。✓ If it rains, the event will be moved indoors.\n✗ will move:将来主动;✗ is moved:一般现在被动;✗ moved:一般过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"\"look forward to\" 的意思是:","options":["期待,盼望","回头看","向前看","往下看"],"answer_index":0,"explanation_cn":"look forward to = 期待、盼望(to 后接名词或动名词)。✓ Everyone looks forward to the festival。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"\"harvest festival\" 的意思是:","options":["收获机器","夏令营","音乐会","丰收节"],"answer_index":3,"explanation_cn":"harvest festival = 丰收节(庆祝收获的节日)。✓ Our town holds a harvest festival every fall。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"How long has the writer been helping to plan the festival?","options":["Two days","Two months","One week","Two years"],"answer_index":1,"passage":"Every fall, our town holds a harvest festival that everyone looks forward to. This year, I have been helping to plan it for two months. Booths were set up near the square, and lights had been hung across it. \"If it rains, the whole event will be moved indoors.\" \"You must try the apple pie,\" my friend said. \"It is being served now.\" Children were laughing while musicians were playing on the stage. By evening, hundreds of people had come, and more were arriving. \"I have never seen the town so alive,\" Grandma said. Next year''s festival will be even bigger, everyone agrees. It was a day that will be remembered for a long time.","explanation_cn":"课文说 I have been helping to plan it for two months。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"What did Grandma say about the town that day?","options":["It was very quiet","It felt cold","She had never seen it so alive","It looked empty"],"answer_index":2,"passage":"Every fall, our town holds a harvest festival that everyone looks forward to. This year, I have been helping to plan it for two months. Booths were set up near the square, and lights had been hung across it. \"If it rains, the whole event will be moved indoors.\" \"You must try the apple pie,\" my friend said. \"It is being served now.\" Children were laughing while musicians were playing on the stage. By evening, hundreds of people had come, and more were arriving. \"I have never seen the town so alive,\" Grandma said. Next year''s festival will be even bigger, everyone agrees. It was a day that will be remembered for a long time.","explanation_cn":"课文说 \"I have never seen the town so alive,\" Grandma said。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"How often is the festival held?","options":["Every ten years","Every fall","Only once","Every month"],"answer_index":1,"audio":"Every fall, our town holds a harvest festival that everyone looks forward to. This year, I have been helping to plan it for two months. Booths were set up near the square, and lights had been hung across it. \"If it rains, the whole event will be moved indoors.\" \"You must try the apple pie,\" my friend said. \"It is being served now.\" Children were laughing while musicians were playing on the stage. By evening, hundreds of people had come, and more were arriving. \"I have never seen the town so alive,\" Grandma said. Next year''s festival will be even bigger, everyone agrees. It was a day that will be remembered for a long time.","explanation_cn":"课文说 Every fall, our town holds a harvest festival。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l95',10,NULL,'choice','{"stem":"What did the friend say you must try?","options":["The cake","The soup","The apple pie","The bread"],"answer_index":2,"audio":"Every fall, our town holds a harvest festival that everyone looks forward to. This year, I have been helping to plan it for two months. Booths were set up near the square, and lights had been hung across it. \"If it rains, the whole event will be moved indoors.\" \"You must try the apple pie,\" my friend said. \"It is being served now.\" Children were laughing while musicians were playing on the stage. By evening, hundreds of people had come, and more were arriving. \"I have never seen the town so alive,\" Grandma said. Next year''s festival will be even bigger, everyone agrees. It was a day that will be remembered for a long time.","explanation_cn":"课文说 \"You must try the apple pie,\" my friend said。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l96',2,12,96,'What''s It Really About?','它到底讲的是什么?','复习 KS22/46/70 形容词/副词 + 介词的固定搭配综合(收官包·方案B换情节):interested in、good at、surprised at、fond of、proud of、afraid of、full of、famous for、grateful to…for、curious about、bored with、pleased with、excited about、keen on、worth doing 等固定搭配的辨析','我姐姐特别喜欢看悬疑小说,也很擅长猜结局。她因为能一天读完一整本书而出名。“我喜欢那种充满意外的故事,”她说。她为自己在最后一页之前就解开谜题而自豪。“别害怕厚厚的书,”她对我说,“要对它们保持好奇。”她读得那么快,我很吃惊。“我很感激作者构思了这么巧妙的情节,”她说。她读书从不厌倦——每一类故事她都喜欢。“一本好书值得读两遍,”她这样认为。现在,我也迫不及待想开始读那本让她爱不释手的书了。','{"q":"Listen and answer — What is the sister interested in?","options":["Mystery novels","Cooking shows","Sports games","Old maps"],"answer_index":0}'::jsonb,'{"title":"复习 KS22/46/70 形容词/副词 + 介词的固定搭配","intro":"很多形容词、副词后面要跟固定的介词,搭配是记住的,不能随便换。本课集中复习:①+ in / at——interested in(对……感兴趣)、good at(擅长)、surprised at(对……感到惊讶);②+ of——fond of(喜爱)、proud of(为……自豪)、afraid of(害怕)、full of(充满);③+ for / to——famous for(因……出名)、grateful to sb for sth(因某事感激某人);④+ about / with / on——curious about(对……好奇)、bored with(厌倦)、pleased with(对……满意)、excited about(对……兴奋)、keen on(热衷于);⑤worth + doing(值得做)。","table":{"headers":["搭配","例子"],"rows":[["+ in / at","interested in books / good at guessing / surprised at how fast"],["+ of","fond of stories / proud of herself / afraid of / full of"],["+ for / to","famous for reading fast / grateful to the author for the plot"],["+ about / with / on","curious about / bored with / pleased with / keen on"],["worth + doing","A good book is worth reading twice."]]},"specialRules":[{"rule":"美语“数学”说 math(英式 maths);“假期”说 vacation(英式 holiday)。本课已按美语写。","mark":"math / vacation"},{"rule":"形容词后的介词是固定搭配:interested in、good at、fond of、famous for、grateful to…for、keen on、curious about、pleased with;worth 后接动名词(worth reading)。","mark":"固定搭配"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l96',1,NULL,'My sister is really interested in mystery novels and good at guessing the ending. She is famous for finishing a whole book in one day.','我姐姐特别喜欢看悬疑小说,也很擅长猜结局。她因为能一天读完一整本书而出名。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l96',2,NULL,'"I''m fond of stories that are full of surprises," she says. She was proud of herself for solving the puzzle before the last page.','“我喜欢那种充满意外的故事,”她说。她为自己在最后一页之前就解开谜题而自豪。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l96',3,NULL,'"Don''t be afraid of long books," she tells me. "Be curious about them." I was surprised at how quickly she read.','“别害怕厚厚的书,”她对我说,“要对它们保持好奇。”她读得那么快,我很吃惊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l96',4,NULL,'"I''m grateful to the author for such a clever plot," she said. She is never bored with reading — she is keen on every kind of story.','“我很感激作者构思了这么巧妙的情节,”她说。她读书从不厌倦——每一类故事她都喜欢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l96',5,NULL,'"A good book is worth reading twice," she believes. Now I''m excited about starting the one she is so pleased with.','“一本好书值得读两遍,”她这样认为。现在,我也迫不及待想开始读那本让她爱不释手的书了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
