INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp1','choice','{"stem":"\"My sister is really interested ___ mystery novels.\"(固定搭配:对……感兴趣)","options":["of","on","in","for"],"answer_index":2,"stem_cn":"我姐姐对悬疑小说很感兴趣。","explanation_cn":"“对……感兴趣”固定搭配 interested in。✓ interested in mystery novels. ✗ on / for / of:与 interested 不搭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp1','choice','{"stem":"\"She is good ___ guessing the ending.\"(固定搭配:擅长)","options":["for","with","in","at"],"answer_index":3,"stem_cn":"她擅长猜结局。","explanation_cn":"“擅长”固定搭配 good at。✓ good at guessing the ending. ✗ in / for / with:与 good 不搭。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp1','choice','{"stem":"\"I was surprised ___ how quickly she read.\"(固定搭配:对……感到惊讶)","options":["at","of","for","in"],"answer_index":0,"stem_cn":"她读得那么快,我很吃惊。","explanation_cn":"“对……感到惊讶”固定搭配 surprised at。✓ surprised at how quickly she read. ✗ of / for / in:与 surprised 不搭。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp2','choice','{"stem":"\"''I''m fond ___ stories full of surprises,'' she says.\"(固定搭配:喜爱)","options":["for","at","of","in"],"answer_index":2,"stem_cn":"“我喜欢充满意外的故事,”她说。","explanation_cn":"“喜爱”固定搭配 fond of。✓ fond of stories full of surprises. ✗ in / at / for:与 fond 不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp2','choice','{"stem":"\"She was proud ___ herself for solving the puzzle.\"(固定搭配:为……自豪)","options":["of","for","at","with"],"answer_index":0,"stem_cn":"她为自己解开谜题而自豪。","explanation_cn":"“为……自豪”固定搭配 proud of。✓ proud of herself. ✗ at / with / for:与 proud 不搭。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp2','choice','{"stem":"\"''Don''t be afraid ___ long books,'' she tells me.\"(固定搭配:害怕)","options":["for","of","at","with"],"answer_index":1,"stem_cn":"“别害怕厚厚的书,”她对我说。","explanation_cn":"“害怕”固定搭配 afraid of。✓ afraid of long books. ✗ at / for / with:与 afraid 不搭。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp3','choice','{"stem":"\"She is famous ___ finishing a whole book in one day.\"(固定搭配:因……出名)","options":["for","in","of","at"],"answer_index":0,"stem_cn":"她因为能一天读完一整本书而出名。","explanation_cn":"“因……出名”固定搭配 famous for。✓ famous for finishing a book in one day. ✗ of / in / at:与 famous 不搭。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp3','choice','{"stem":"\"''I''m grateful ___ the author for such a clever plot,'' she said.\"(固定搭配:感激某人)","options":["for","to","of","with"],"answer_index":1,"stem_cn":"“我很感激作者,”她说。","explanation_cn":"“感激某人”固定搭配 grateful to sb。✓ grateful to the author. ✗ for:后面接感激的“事”,这里接的是“人”;✗ of / with:与 grateful 不搭。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp3','choice','{"stem":"\"I''m grateful to the author ___ such a clever plot.\"(固定搭配:因某事而感激)","options":["at","of","to","for"],"answer_index":3,"stem_cn":"我因这么巧妙的情节而感激作者。","explanation_cn":"“因某事而感激”固定搭配 grateful to sb for sth,这里接“事”。✓ grateful to the author for such a clever plot. ✗ to:后面接“人”;✗ of / at:与 grateful 不搭。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp4','choice','{"stem":"\"''Be curious ___ long books,'' she says.\"(固定搭配:对……好奇)","options":["at","of","about","for"],"answer_index":2,"stem_cn":"“要对厚厚的书保持好奇,”她说。","explanation_cn":"“对……好奇”固定搭配 curious about。✓ curious about long books. ✗ of / at / for:与 curious 不搭。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp4','choice','{"stem":"\"She is never bored ___ reading.\"(固定搭配:对……厌倦)","options":["at","of","for","with"],"answer_index":3,"stem_cn":"她读书从不厌倦。","explanation_cn":"“对……厌倦”固定搭配 bored with。✓ bored with reading. ✗ of / at / for:与 bored 不搭。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp4','choice','{"stem":"\"Now I''m excited ___ starting a new book.\"(固定搭配:对……兴奋)","options":["about","at","in","of"],"answer_index":0,"stem_cn":"现在我很兴奋要开始读一本新书。","explanation_cn":"“对……兴奋”固定搭配 excited about。✓ excited about starting a new book. ✗ of / at / in:与 excited 不搭。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp5','choice','{"stem":"\"She is keen ___ every kind of story.\"(固定搭配:热衷于)","options":["for","at","of","on"],"answer_index":3,"stem_cn":"每一类故事她都喜欢。","explanation_cn":"“热衷于”固定搭配 keen on。✓ keen on every kind of story. ✗ at / of / for:与 keen 不搭。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp5','choice','{"stem":"\"She is very pleased ___ her new book.\"(固定搭配:对……满意)","options":["for","of","with","at"],"answer_index":2,"stem_cn":"她对自己的新书很满意。","explanation_cn":"“对……满意”固定搭配 pleased with。✓ pleased with her new book. ✗ of / at / for:与 pleased 不搭。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp5','choice','{"stem":"\"A story full ___ surprises is fun to read.\"(固定搭配:充满)","options":["of","at","in","with"],"answer_index":0,"stem_cn":"充满意外的故事读起来很有意思。","explanation_cn":"“充满”固定搭配 full of。✓ a story full of surprises. ✗ with / in / at:与 full 不搭。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp6','choice','{"stem":"\"She loves reading ___ stories with hidden clues.\"(悬疑、推理用哪个词)","options":["travel","sports","cooking","mystery"],"answer_index":3,"stem_cn":"她喜欢读带有隐藏线索的悬疑故事。","explanation_cn":"带隐藏线索、悬念的“悬疑、推理”是 mystery。✓ mystery stories with hidden clues. ✗ cooking:烹饪;✗ sports:运动;✗ travel:旅行。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp6','choice','{"stem":"\"She solved the ___ before the last page.\"(谜题用哪个词)","options":["puzzle","dinner","ticket","garden"],"answer_index":0,"stem_cn":"她在最后一页之前就解开了谜题。","explanation_cn":"需要动脑解开的“谜题、难题”是 puzzle。✓ solved the puzzle. ✗ dinner:晚饭;✗ ticket:门票;✗ garden:花园。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',5,'am2_l96_gp6','choice','{"stem":"\"The clever ___ of the story surprised everyone.\"(情节用哪个词)","options":["weight","plot","price","weather"],"answer_index":1,"stem_cn":"故事巧妙的情节让所有人都惊讶。","explanation_cn":"故事的“情节”是 plot。✓ the clever plot of the story. ✗ weather:天气;✗ price:价格;✗ weight:重量。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',6,NULL,'choice','{"stem":"美语里\"数学\"说:","options":["math","maths","sums","number-work"],"answer_index":0,"explanation_cn":"美语“数学”说 math;英式说 maths。✓ She is good at math. 她擅长数学。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',6,NULL,'choice','{"stem":"美语里\"假期\"说:","options":["holiday","days-off","vacation","break"],"answer_index":2,"explanation_cn":"美语“假期”说 vacation;英式说 holiday。✓ She read ten books over the vacation. 假期里她读了十本书。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',6,NULL,'choice','{"stem":"mystery 的意思是:","options":["历史","诗歌","喜剧","悬疑,谜"],"answer_index":3,"explanation_cn":"mystery = 悬疑、谜。✓ mystery novels 悬疑小说。\n顺带记:喜剧 = comedy;历史 = history;诗歌 = poetry."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',6,NULL,'choice','{"stem":"curious 的意思是:","options":["厌倦的","生气的","好奇的","害怕的"],"answer_index":2,"explanation_cn":"curious = 好奇的。✓ Be curious about them. 要对它们保持好奇。\n顺带记:厌倦的 = bored;害怕的 = afraid;生气的 = angry."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',6,NULL,'choice','{"stem":"ending 的意思是:","options":["结局,结尾","目录","封面","开头"],"answer_index":0,"explanation_cn":"ending = 结局、结尾。✓ guessing the ending 猜结局。\n顺带记:开头 = beginning;封面 = cover;目录 = contents."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',6,NULL,'choice','{"stem":"guess 的意思是:","options":["忘记","出售","打碎","猜测"],"answer_index":3,"explanation_cn":"guess = 猜测。✓ good at guessing 擅长猜。\n顺带记:忘记 = forget;出售 = sell;打碎 = break."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',7,NULL,'cloze','{"stem":"第 1 空","context":"My sister is interested ___1___ mystery novels and good ___2___ guessing the ending. She is famous ___3___ reading fast. \"Don''t be afraid ___4___ long books,\" she says.","blank_no":1,"options":["in","on","for","of"],"answer_index":0,"explanation_cn":"“对……感兴趣”固定搭配 interested in。✓ interested in mystery novels.\n✗ on / for / of:与 interested 不搭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
