INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',7,NULL,'cloze','{"stem":"第 4 空","context":"My sister is interested ___1___ mystery novels and good ___2___ guessing the ending. She is famous ___3___ reading fast. \"Don''t be afraid ___4___ long books,\" she says.","blank_no":4,"options":["of","at","for","with"],"answer_index":0,"explanation_cn":"“害怕”固定搭配 afraid of。✓ afraid of long books.\n✗ at / for / with:与 afraid 不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',8,NULL,'choice','{"stem":"What is the sister interested in?","options":["Sports","Old maps","Mystery novels","Cooking shows"],"answer_index":2,"explanation_cn":"课文说 My sister is really interested in mystery novels。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
