INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',8,NULL,'choice','{"stem":"What does she say about long books?","options":["Don''t be afraid of them; be curious","They are too hard","They are boring","Never read them"],"answer_index":0,"explanation_cn":"课文说 \"Don''t be afraid of long books,\" she tells me. \"Be curious about them.\""}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',9,NULL,'choice','{"stem":"你想说\"我姐姐对悬疑小说很感兴趣\"(固定搭配 interested in):","options":["My sister is really interested on mystery novels.","My sister is really interested in mystery novels.","My sister is really interested of mystery novels.","My sister is really interested for mystery novels."],"answer_index":1,"explanation_cn":"“对……感兴趣”固定搭配 interested in。✓ My sister is really interested in mystery novels. 场合:说某人对某事物感兴趣。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',9,NULL,'choice','{"stem":"你想说\"她擅长猜结局\"(固定搭配 good at):","options":["She is good for guessing the ending.","She is good in guessing the ending.","She is good at guessing the ending.","She is good on guessing the ending."],"answer_index":2,"explanation_cn":"“擅长”固定搭配 good at + 动名词。✓ She is good at guessing the ending. 场合:说某人擅长做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
