INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"puzzle 的意思是:","options":["地图","谜题,难题","工具","礼物"],"answer_index":1,"explanation_cn":"puzzle = 谜题、难题。✓ solved the puzzle 解开谜题。\n顺带记:礼物 = gift;工具 = tool;地图 = map."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"\"My sister is interested ___ mystery novels.\"(固定搭配)","options":["in","of","on","for"],"answer_index":0,"stem_cn":"我姐姐对悬疑小说很感兴趣。","explanation_cn":"“对……感兴趣”固定搭配 interested in。✓ interested in mystery novels.\n✗ on / for / of:与 interested 不搭。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"\"She is good ___ guessing the ending.\"(固定搭配)","options":["for","with","at","in"],"answer_index":2,"stem_cn":"她擅长猜结局。","explanation_cn":"“擅长”固定搭配 good at。✓ good at guessing the ending.\n✗ in / for / with:与 good 不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"\"worth reading\" 的意思是:","options":["值得一读","正在读","读过了","读得起"],"answer_index":0,"explanation_cn":"worth reading = 值得一读(worth + 动名词)。✓ A good book is worth reading twice。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"\"keen on\" 的意思是:","options":["反对","热衷于,喜爱","靠近","依赖"],"answer_index":1,"explanation_cn":"keen on = 热衷于、喜爱。✓ She is keen on every kind of story。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"What is the sister good at?","options":["Writing books","Cooking","Guessing the ending","Drawing maps"],"answer_index":2,"passage":"My sister is really interested in mystery novels and good at guessing the ending. She is famous for finishing a whole book in one day. \"I''m fond of stories that are full of surprises,\" she says. She was proud of herself for solving the puzzle before the last page. \"Don''t be afraid of long books,\" she tells me. \"Be curious about them.\" I was surprised at how quickly she read. \"I''m grateful to the author for such a clever plot,\" she said. She is never bored with reading — she is keen on every kind of story. \"A good book is worth reading twice,\" she believes. Now I''m excited about starting the one she is so pleased with.","explanation_cn":"课文说 good at guessing the ending——她擅长猜结局。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"What is the sister famous for?","options":["Finishing a whole book in one day","Telling jokes","Winning contests","Solving math problems"],"answer_index":0,"passage":"My sister is really interested in mystery novels and good at guessing the ending. She is famous for finishing a whole book in one day. \"I''m fond of stories that are full of surprises,\" she says. She was proud of herself for solving the puzzle before the last page. \"Don''t be afraid of long books,\" she tells me. \"Be curious about them.\" I was surprised at how quickly she read. \"I''m grateful to the author for such a clever plot,\" she said. She is never bored with reading — she is keen on every kind of story. \"A good book is worth reading twice,\" she believes. Now I''m excited about starting the one she is so pleased with.","explanation_cn":"课文说 She is famous for finishing a whole book in one day。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"What kind of novels is the sister interested in?","options":["Poetry","Mystery novels","Comics","History books"],"answer_index":1,"audio":"My sister is really interested in mystery novels and good at guessing the ending. She is famous for finishing a whole book in one day. \"I''m fond of stories that are full of surprises,\" she says. She was proud of herself for solving the puzzle before the last page. \"Don''t be afraid of long books,\" she tells me. \"Be curious about them.\" I was surprised at how quickly she read. \"I''m grateful to the author for such a clever plot,\" she said. She is never bored with reading — she is keen on every kind of story. \"A good book is worth reading twice,\" she believes. Now I''m excited about starting the one she is so pleased with.","explanation_cn":"课文说 My sister is really interested in mystery novels。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l96',10,NULL,'choice','{"stem":"What does she say about a good book?","options":["It''s worth reading twice","It''s easy","It''s boring","It''s too long"],"answer_index":0,"audio":"My sister is really interested in mystery novels and good at guessing the ending. She is famous for finishing a whole book in one day. \"I''m fond of stories that are full of surprises,\" she says. She was proud of herself for solving the puzzle before the last page. \"Don''t be afraid of long books,\" she tells me. \"Be curious about them.\" I was surprised at how quickly she read. \"I''m grateful to the author for such a clever plot,\" she said. She is never bored with reading — she is keen on every kind of story. \"A good book is worth reading twice,\" she believes. Now I''m excited about starting the one she is so pleased with.","explanation_cn":"课文说 \"A good book is worth reading twice,\" she believes。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
